import SwiftUI
import AppKit

final class AppDelegate: NSObject, NSApplicationDelegate {
    // QDL keeps running in the menu bar when its window is closed.
    func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool { false }
}

@main
struct QDLApp: App {
    @NSApplicationDelegateAdaptor(AppDelegate.self) private var appDelegate
    @StateObject private var model = AppModel()

    var body: some Scene {
        WindowGroup("QDL", id: "main") {
            RootView()
                .environmentObject(model)
                .environmentObject(model.catalog)
                .environmentObject(model.player)
                .environmentObject(model.updater)
                .environmentObject(model.library)
                .frame(minWidth: 1120, minHeight: 700)
        }
        .windowStyle(.hiddenTitleBar)
        .defaultSize(width: 1280, height: 840)
        .commands {
            CommandGroup(after: .appSettings) {
                Button("Qobuz Account…") { model.showAccount = true }
                    .keyboardShortcut("a", modifiers: [.command, .option])
                Button("Appearance…") { model.showAppearance = true }
                    .keyboardShortcut(",", modifiers: [.command, .option])
                Divider()
                Button("Check for Updates…") { Task { await model.updater.check(silent: false) } }
                Button("Update Download Engine") { Task { await model.updateEngine() } }
                    .disabled(model.isRunning)
            }
            CommandGroup(replacing: .newItem) {}
            CommandGroup(after: .pasteboard) {
                Divider()
                Button("Paste and Open Link") { model.pasteAndOpen() }
                    .keyboardShortcut("v", modifiers: [.command, .shift])
            }
            CommandMenu("Go") {
                Button("Store") { model.go(.store) }
                    .keyboardShortcut("1", modifiers: .command)
                Button("Album") { model.go(.album) }
                    .keyboardShortcut("2", modifiers: .command)
                Button("My Qobuz") { model.go(.mine) }
                    .keyboardShortcut("3", modifiers: .command)
                Button("Library") { model.go(.library) }
                    .keyboardShortcut("4", modifiers: .command)
                Button("Downloads") { model.go(.downloads) }
                    .keyboardShortcut("5", modifiers: .command)
                Divider()
                Button("Back") { model.goBack() }
                    .disabled(!model.canGoBack)
            }
            CommandMenu("Playback") {
                Button(model.player.isPlaying ? "Pause Preview" : "Play Preview") { model.player.toggle() }
                    .keyboardShortcut("p", modifiers: [.command, .option])
                    .disabled(model.player.current == nil)
                Button("Stop Preview") { model.player.stop() }
                    .disabled(model.player.current == nil)
            }
        }

        Settings {
            SettingsView()
                .environmentObject(model)
                .environmentObject(model.updater)
                .environmentObject(model.library)
        }

        MenuBarExtra("QDL", systemImage: "waveform") {
            MenuBarPanel()
                .environmentObject(model)
                .environmentObject(model.updater)
        }
        .menuBarExtraStyle(.window)
    }
}

