import Foundation

// MARK: - Download settings

enum AudioQuality: Int, CaseIterable, Identifiable {
    case mp3 = 1
    case cd = 2
    case hiRes = 3
    case hiResMax = 4

    var id: Int { rawValue }

    var label: String {
        switch self {
        case .mp3: return "MP3"
        case .cd: return "CD"
        case .hiRes: return "Hi-Res"
        case .hiResMax: return "Max"
        }
    }

    var sub: String {
        switch self {
        case .mp3: return "320 kbps"
        case .cd: return "16 / 44.1"
        case .hiRes: return "24 / 96"
        case .hiResMax: return "24 / 192"
        }
    }
}

enum OutputFormat: String, CaseIterable, Identifiable {
    case original, wav, alac, aac, mp3

    var id: String { rawValue }

    var label: String {
        switch self {
        case .original: return "Original (FLAC)"
        case .wav: return "WAV · uncompressed"
        case .alac: return "ALAC · Apple Lossless"
        case .aac: return "AAC"
        case .mp3: return "MP3"
        }
    }

    var short: String {
        switch self {
        case .original: return "FLAC"
        case .wav: return "WAV"
        case .alac: return "ALAC"
        case .aac: return "AAC"
        case .mp3: return "MP3"
        }
    }

    /// Value for streamrip's --codec flag. nil = keep what Qobuz delivers
    /// (WAV is downloaded as FLAC and converted by QDL afterwards).
    var codecArgument: String? {
        switch self {
        case .original, .wav: return nil
        case .alac: return "ALAC"
        case .aac: return "AAC"
        case .mp3: return "MP3"
        }
    }
}

enum AuthMethod: String, CaseIterable, Identifiable {
    case token, email

    var id: String { rawValue }

    var label: String {
        switch self {
        case .token: return "User ID + Token"
        case .email: return "Email + Password"
        }
    }

    var keychainAccount: String { self == .token ? "qobuz-token" : "qobuz-password" }
    var savedFlagKey: String { "hasSecret.\(rawValue)" }
}

// MARK: - Links

struct QobuzLink {
    let kind: String   // album, track, playlist, artist, label
    let id: String
    let url: String

    static func parse(_ text: String) -> QobuzLink? {
        let junk = CharacterSet(charactersIn: "<>\"'(),")
        for token in text.components(separatedBy: .whitespacesAndNewlines) {
            let link = token.trimmingCharacters(in: junk)
            guard link.lowercased().hasPrefix("http"), link.lowercased().contains("qobuz.com"),
                  let u = URL(string: link) else { continue }
            let parts = u.pathComponents.filter { $0 != "/" }
            let kinds = ["album", "track", "playlist", "artist", "label"]
            guard let i = parts.firstIndex(where: { kinds.contains($0.lowercased()) }),
                  let last = parts.last, i < parts.count - 1 else { continue }
            return QobuzLink(kind: parts[i].lowercased(), id: last, url: link)
        }
        return nil
    }

    /// A readable name from the link's slug, for kinds we don't preview.
    var guessedName: String {
        guard let u = URL(string: url) else { return kind.capitalized }
        let parts = u.pathComponents.filter { $0 != "/" }
        if let i = parts.firstIndex(where: { $0.lowercased() == kind }), parts.count - i >= 3 {
            return parts[i + 1].replacingOccurrences(of: "-", with: " ").capitalized
        }
        return kind.capitalized
    }
}

// MARK: - Preview (album / track metadata from Qobuz)

struct PreviewTrack: Identifiable, Equatable {
    let id: String
    let number: Int
    let disc: Int
    let title: String
    let artist: String?
    let duration: Int
    let bitDepth: Int
    let sampleRate: Double
    let streamable: Bool
    let explicit: Bool
    var performers: String? = nil
    var coverURL: URL? = nil
    var album: String? = nil

    var durationText: String { String(format: "%d:%02d", duration / 60, duration % 60) }
    var qualityText: String { Preview.qualityText(bitDepth: bitDepth, rate: sampleRate) }
}

struct Preview: Equatable {
    let kind: String
    let id: String
    let link: String
    let title: String
    let artist: String
    let year: String?
    let genre: String?
    let label: String?
    let coverURL: URL?
    let maxBitDepth: Int
    let maxSampleRate: Double
    let tracks: [PreviewTrack]
    /// Artists and labels are downloaded whole, without a track list.
    let isWholeOnly: Bool
    var booklets: [Booklet] = []
    var artistID: String? = nil

    var discCount: Int { Set(tracks.map(\.disc)).count }
    var totalSeconds: Int { tracks.reduce(0) { $0 + $1.duration } }

    var bestQuality: AudioQuality {
        if maxBitDepth >= 24 && maxSampleRate > 96.0 { return .hiResMax }
        if maxBitDepth >= 24 { return .hiRes }
        if maxBitDepth > 0 { return .cd }
        return .hiResMax
    }

    var bestText: String {
        maxBitDepth > 0 ? Preview.qualityText(bitDepth: maxBitDepth, rate: maxSampleRate) : "—"
    }

    static func qualityText(bitDepth: Int, rate: Double) -> String {
        guard bitDepth > 0 else { return "—" }
        let r = rate.rounded() == rate ? String(Int(rate)) : String(format: "%.1f", rate)
        return "\(bitDepth) / \(r)"
    }

    static func wholeOnly(_ link: QobuzLink) -> Preview {
        Preview(kind: link.kind, id: link.id, link: link.url, title: link.guessedName,
                artist: link.kind.capitalized, year: nil, genre: nil, label: nil, coverURL: nil,
                maxBitDepth: 0, maxSampleRate: 0, tracks: [], isWholeOnly: true)
    }
}

struct Booklet: Identifiable, Equatable {
    var id: URL { url }
    let name: String
    let url: URL
}

// MARK: - Download jobs

enum TrackStatus: Equatable {
    case waiting, running, done, failed(String), cancelled
}

struct JobTrack: Identifiable, Equatable {
    let id: String
    let number: Int
    let title: String
    var status: TrackStatus = .waiting
}

enum JobStatus: Equatable {
    case queued
    case running
    case done
    case warning(String)
    case failed(String)
    case cancelled

    var isFinished: Bool {
        switch self {
        case .queued, .running: return false
        default: return true
        }
    }
}

struct DownloadJob: Identifiable, Equatable {
    let id = UUID()
    let title: String
    let artist: String
    let coverURL: URL?
    let link: String
    let kind: String
    let quality: AudioQuality
    let format: OutputFormat
    let qualityText: String
    /// true = one streamrip run for the whole release; false = one run per track in tracks.
    let wholeRelease: Bool
    var tracks: [JobTrack]
    var status: JobStatus = .queued
    var finishedAt: Date?
    var filters: DiscographyFilters? = nil
    var albumID: String? = nil
    var bestBitDepth: Int = 0
    var bestRate: Double = 0

    var doneCount: Int { tracks.filter { $0.status == .done }.count }
    var progress: Double {
        guard !tracks.isEmpty else { return status == .done ? 1 : 0 }
        let finished = tracks.filter { t in
            switch t.status { case .done, .failed, .cancelled: return true; default: return false }
        }.count
        return Double(finished) / Double(tracks.count)
    }
}

/// streamrip's [qobuz_filters] for artist discographies.
struct DiscographyFilters: Equatable {
    var extras = true        // skip collector's editions, live recordings, etc.
    var repeats = true       // keep only the best-quality copy of same-titled albums
    var nonAlbums = false    // skip EPs and singles
    var features = true      // skip albums where the artist is only a guest
    var nonStudio = true     // skip non-studio albums
    var nonRemaster = false  // only remastered albums

    static let off = DiscographyFilters(extras: false, repeats: false, nonAlbums: false,
                                         features: false, nonStudio: false, nonRemaster: false)
}

// MARK: - Folder naming (streamrip [filepaths])

enum FolderPreset: String, CaseIterable, Identifiable {
    case standard, yearAlbum, albumQuality, album, custom
    var id: String { rawValue }

    var label: String {
        switch self {
        case .standard: return "Artist - Album (Year) [FLAC] [24B-96kHz]"
        case .yearAlbum: return "Year – Album [24-96]"
        case .albumQuality: return "Album [24-96]"
        case .album: return "Album"
        case .custom: return "Custom…"
        }
    }

    var template: String? {
        switch self {
        case .standard: return "{albumartist} - {title} ({year}) [{container}] [{bit_depth}B-{sampling_rate}kHz]"
        case .yearAlbum: return "{year} – {title} [{bit_depth}-{sampling_rate}]"
        case .albumQuality: return "{title} [{bit_depth}-{sampling_rate}]"
        case .album: return "{title}"
        case .custom: return nil
        }
    }
}

enum TrackPreset: String, CaseIterable, Identifiable {
    case standard, numberTitle, title, custom
    var id: String { rawValue }

    var label: String {
        switch self {
        case .standard: return "01. Artist - Title"
        case .numberTitle: return "01. Title"
        case .title: return "Title"
        case .custom: return "Custom…"
        }
    }

    var template: String? {
        switch self {
        case .standard: return "{tracknumber:02}. {artist} - {title}{explicit}"
        case .numberTitle: return "{tracknumber:02}. {title}"
        case .title: return "{title}"
        case .custom: return nil
        }
    }
}

enum NamingSample {
    static let values: [String: String] = [
        "albumartist": "Juniper Vale", "artist": "Juniper Vale", "title": "Low Tide Hours", "year": "2024",
        "container": "FLAC", "bit_depth": "24", "sampling_rate": "96", "tracknumber:02": "01",
        "tracknumber": "1", "explicit": "", "albumcomposer": "J. Vale", "composer": "J. Vale", "id": "0123456789",
    ]

    static func render(_ template: String, track: Bool = false) -> String {
        var s = template
        for (k, v) in values {
            s = s.replacingOccurrences(of: "{\(k)}", with: k == "title" && track ? "Harbour Lights" : v)
        }
        return s
    }

    static func safeFolderName(_ s: String) -> String {
        let bad = CharacterSet(charactersIn: "/:\\?%*|\"<>")
        return s.components(separatedBy: bad).joined(separator: "-").trimmed
    }
}

struct RecentItem: Identifiable, Equatable {
    var id: String { link }
    let title: String
    let artist: String
    let link: String
    let coverURL: URL?
}

struct LogLine: Identifiable {
    let id = UUID()
    let text: String
    let isError: Bool
}

extension String {
    var trimmed: String { trimmingCharacters(in: .whitespacesAndNewlines) }
}

