import SwiftUI
import AppKit

// MARK: - Root

struct RootView: View {
    @EnvironmentObject var model: AppModel
    @Environment(\.colorScheme) private var scheme

    var body: some View {
        let theme = model.theme(for: scheme)
        ZStack {
            AuroraBackground()
            VStack(spacing: 10) {
                TopBar()
                HStack(alignment: .top, spacing: 12) {
                    Sidebar()
                        .frame(width: 232)
                    Group {
                        switch model.pane {
                        case .store: StoreView()
                        case .album: BrowseView()
                        case .artist: ArtistView()
                        case .mine: MyQobuzView()
                        case .library: LibraryView()
                        case .downloads: DownloadsView()
                        }
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                }
                .padding(.horizontal, 12)
                .padding(.bottom, 12)
            }
        }
        .environment(\.qdl, theme)
        .foregroundStyle(theme.text)
        .tint(theme.accent)
        .preferredColorScheme(model.themeChoice.colorScheme)
        .sheet(isPresented: $model.showAccount) {
            AccountSheet()
                .environmentObject(model)
                .environment(\.qdl, theme)
        }
    }
}

// MARK: - Shared pieces

struct Segmented<T: Hashable>: View {
    @Environment(\.qdl) private var t
    let options: [T]
    @Binding var selection: T
    let label: (T) -> String
    var sub: ((T) -> String)? = nil
    var height: CGFloat = 30

    var body: some View {
        HStack(spacing: 2) {
            ForEach(options, id: \.self) { o in
                let on = o == selection
                Button {
                    withAnimation(.spring(response: 0.35, dampingFraction: 0.8)) { selection = o }
                } label: {
                    VStack(spacing: 0) {
                        Text(label(o)).font(.system(size: 13, weight: .semibold))
                        if let sub {
                            Text(sub(o)).font(.system(size: 10.5))
                        }
                    }
                    .foregroundStyle(on ? t.text : t.sub)
                    .frame(maxWidth: .infinity, minHeight: height)
                    .padding(.horizontal, 8)
                    .background {
                        if on {
                            Capsule()
                                .fill(t.segOn)
                                .shadow(color: .black.opacity(t.isDark ? 0 : 0.12), radius: 2, y: 1)
                        }
                    }
                    .contentShape(Capsule())
                }
                .buttonStyle(.plain)
                .accessibilityAddTraits(on ? .isSelected : [])
            }
        }
        .padding(3)
        .background(Capsule().fill(t.control))
    }
}

struct CoverView: View {
    var image: NSImage? = nil
    var url: URL? = nil
    let size: CGFloat
    let radius: CGFloat

    var body: some View {
        Group {
            if let image {
                Image(nsImage: image).resizable().aspectRatio(contentMode: .fill)
            } else if let url {
                AsyncImage(url: url) { img in
                    img.resizable().aspectRatio(contentMode: .fill)
                } placeholder: {
                    placeholder
                }
            } else {
                placeholder
            }
        }
        .frame(width: size, height: size)
        .clipShape(RoundedRectangle(cornerRadius: radius, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: radius, style: .continuous).strokeBorder(Color.white.opacity(0.12)))
        .accessibilityHidden(true)
    }

    private var placeholder: some View {
        ZStack {
            LinearGradient(colors: [Color(hex: 0x2E6E86), Color(hex: 0x0E2233)], startPoint: .top, endPoint: .bottom)
            Image(systemName: "music.note")
                .font(.system(size: size * 0.3, weight: .light))
                .foregroundStyle(Color.white.opacity(0.55))
        }
    }
}

struct Badge: View {
    @Environment(\.qdl) private var t
    let text: String
    var gold = false

    var body: some View {
        Text(text)
            .font(.system(size: 11.5, weight: .semibold))
            .padding(.horizontal, 10)
            .padding(.vertical, 4)
            .foregroundStyle(gold ? t.badgeText : t.text)
            .background(Capsule().fill(gold ? t.badgeFill : t.control))
    }
}

struct AccentButton: View {
    @Environment(\.qdl) private var t
    let title: String
    let icon: String
    var enabled = true
    let action: () -> Void

    var body: some View {
        Button(action: action) {
            Label(title, systemImage: icon)
                .font(.system(size: 14, weight: .semibold))
                .padding(.horizontal, 20)
                .frame(height: 44)
                .foregroundStyle(enabled ? t.buttonText : t.sub)
                .background(Capsule().fill(enabled ? t.button : t.control))
                .overlay(Capsule().strokeBorder(Color.white.opacity(enabled ? 0.18 : 0)))
                .contentShape(Capsule())
        }
        .buttonStyle(.plain)
        .disabled(!enabled)
    }
}

// MARK: - Top bar

struct TopBar: View {
    @EnvironmentObject var model: AppModel
    @Environment(\.qdl) private var t

    var body: some View {
        HStack(spacing: 10) {
            Button {
                model.goBack()
            } label: {
                Image(systemName: "chevron.left")
                    .font(.system(size: 14, weight: .semibold))
                    .frame(width: 36, height: 36)
                    .contentShape(Circle())
            }
            .buttonStyle(.plain)
            .glass(18)
            .disabled(!model.canGoBack)
            .opacity(model.canGoBack ? 1 : 0.45)
            .help("Back")
            .accessibilityLabel("Back")
            .keyboardShortcut("[", modifiers: .command)

            HStack(spacing: 8) {
                Image(systemName: QobuzLink.parse(model.linkField) == nil ? "magnifyingglass" : "link")
                    .font(.system(size: 13))
                    .foregroundStyle(t.sub)
                TextField("Search Qobuz — artists, albums, tracks — or paste a link", text: $model.linkField)
                    .textFieldStyle(.plain)
                    .font(.system(size: 13))
                    .onSubmit { model.submit(model.linkField) }
                if let kind = QobuzLink.parse(model.linkField)?.kind {
                    Text(kind.uppercased())
                        .font(.system(size: 10.5, weight: .semibold))
                        .padding(.horizontal, 8)
                        .padding(.vertical, 3)
                        .foregroundStyle(t.accentText)
                        .background(Capsule().fill(t.accentSoft))
                }
                Button {
                    model.submit(model.linkField)
                } label: {
                    Image(systemName: "arrow.right.circle.fill").font(.system(size: 19))
                }
                .buttonStyle(.plain)
                .foregroundStyle(t.accent)
                .help("Search or open link")
                .accessibilityLabel("Search or open link")
                .disabled(model.linkField.trimmed.isEmpty)
            }
            .padding(.leading, 14)
            .padding(.trailing, 8)
            .frame(height: 36)
            .glass(18)

            Button {
                model.pasteAndOpen()
            } label: {
                Label("Paste", systemImage: "doc.on.clipboard")
                    .font(.system(size: 13, weight: .medium))
                    .padding(.horizontal, 14)
                    .frame(height: 36)
                    .contentShape(Capsule())
            }
            .buttonStyle(.plain)
            .glass(18)
            .help("Paste a link and open it (⇧⌘V)")

            Button {
                model.showAppearance.toggle()
            } label: {
                Image(systemName: "circle.lefthalf.filled")
                    .font(.system(size: 15))
                    .frame(width: 36, height: 36)
                    .contentShape(Circle())
            }
            .buttonStyle(.plain)
            .glass(18)
            .help("Appearance")
            .accessibilityLabel("Appearance")
            .popover(isPresented: $model.showAppearance, arrowEdge: .bottom) {
                AppearancePanel()
                    .environmentObject(model)
                    .environment(\.qdl, t)
            }
        }
        .padding(.leading, 78)
        .padding(.trailing, 12)
        .padding(.top, 8)
    }
}

// MARK: - Sidebar

struct Sidebar: View {
    @EnvironmentObject var model: AppModel
    @Environment(\.qdl) private var t

    var body: some View {
        VStack(alignment: .leading, spacing: 2) {
            HStack(spacing: 8) {
                Image(systemName: "waveform")
                    .font(.system(size: 18, weight: .semibold))
                    .foregroundStyle(t.accent)
                Text("QDL").font(.system(size: 17, weight: .bold))
            }
            .padding(.horizontal, 10)
            .padding(.bottom, 12)

            NavItem(title: "Store", icon: "bag", pane: .store)
            NavItem(title: model.preview?.kind == "playlist" ? "Playlist" : "Album", icon: "square.stack", pane: .album)
            NavItem(title: "My Qobuz", icon: "heart", pane: .mine)
            NavItem(title: "Library", icon: "music.note.house", pane: .library)
            NavItem(title: "Downloads", icon: "arrow.down.circle", pane: .downloads, badge: model.activeCount)

            if !model.recent.isEmpty {
                Text("RECENT")
                    .font(.system(size: 11, weight: .semibold))
                    .foregroundStyle(t.sub)
                    .padding(.horizontal, 10)
                    .padding(.top, 18)
                    .padding(.bottom, 4)
                ForEach(model.recent) { r in
                    Button {
                        model.openLink(r.link)
                    } label: {
                        HStack(spacing: 10) {
                            CoverView(url: r.coverURL, size: 30, radius: 6)
                            VStack(alignment: .leading, spacing: 0) {
                                Text(r.title).font(.system(size: 13)).lineLimit(1)
                                Text(r.artist).font(.system(size: 11)).foregroundStyle(t.sub).lineLimit(1)
                            }
                            Spacer(minLength: 0)
                        }
                        .padding(.horizontal, 8)
                        .padding(.vertical, 4)
                        .contentShape(Rectangle())
                    }
                    .buttonStyle(.plain)
                }
            }

            Spacer(minLength: 12)
            MiniPlayer()
                .padding(.bottom, 8)
            UpdateBanner()
                .padding(.bottom, 8)
            EngineStatus()
                .padding(.bottom, 8)
            AccountCard()
        }
        .padding(.vertical, 16)
        .padding(.horizontal, 10)
        .frame(maxHeight: .infinity, alignment: .top)
        .glass(20)
    }
}

struct NavItem: View {
    @EnvironmentObject var model: AppModel
    @Environment(\.qdl) private var t
    let title: String
    let icon: String
    let pane: Pane
    var badge = 0

    var body: some View {
        let on = model.pane == pane
        Button {
            model.go(pane)
        } label: {
            HStack(spacing: 10) {
                Image(systemName: icon)
                    .frame(width: 18)
                    .foregroundStyle(on ? t.accent : t.sub)
                Text(title).font(.system(size: 14, weight: on ? .semibold : .regular))
                Spacer()
                if badge > 0 {
                    Text("\(badge)")
                        .font(.system(size: 11, weight: .bold))
                        .foregroundStyle(t.buttonText)
                        .padding(.horizontal, 7)
                        .frame(minWidth: 20, minHeight: 20)
                        .background(Capsule().fill(t.button))
                }
            }
            .padding(.horizontal, 10)
            .frame(height: 36)
            .background(RoundedRectangle(cornerRadius: 10, style: .continuous).fill(on ? t.segOn.opacity(t.isDark ? 0.7 : 1) : Color.clear))
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .accessibilityAddTraits(on ? .isSelected : [])
    }
}

struct EngineStatus: View {
    @EnvironmentObject var model: AppModel
    @Environment(\.qdl) private var t
    private let brewCommand = #"/bin/bash -c "$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)""#

    var body: some View {
        switch model.engine {
        case .ready(let version):
            HStack(spacing: 7) {
                Circle().fill(Color.green).frame(width: 7, height: 7)
                Text("Engine ready · streamrip \(version)")
                    .font(.system(size: 11.5))
                    .foregroundStyle(t.sub)
            }
            .padding(.horizontal, 10)
        case .checking:
            HStack(spacing: 8) {
                ProgressView().controlSize(.small)
                Text("Checking engine…").font(.system(size: 12)).foregroundStyle(t.sub)
            }
            .padding(.horizontal, 10)
        case .installing:
            HStack(spacing: 8) {
                ProgressView().controlSize(.small)
                Text("Installing engine…").font(.system(size: 12)).foregroundStyle(t.sub)
            }
            .padding(.horizontal, 10)
        case .missing:
            VStack(alignment: .leading, spacing: 8) {
                Text("Download engine not installed").font(.system(size: 12.5, weight: .semibold))
                Text("QDL uses streamrip and ffmpeg. Install them once:")
                    .font(.system(size: 11.5))
                    .foregroundStyle(t.sub)
                    .fixedSize(horizontal: false, vertical: true)
                HStack {
                    Button("Install Engine") { Task { await model.installEngine() } }
                        .buttonStyle(.borderedProminent)
                        .controlSize(.small)
                        .disabled(model.isRunning)
                    Button("Check Again") { Task { await model.checkEngine() } }
                        .controlSize(.small)
                }
                if model.homebrewMissing {
                    Text("Homebrew is needed first. Paste this into Terminal, then click Install Engine:")
                        .font(.system(size: 11))
                        .foregroundStyle(t.sub)
                        .fixedSize(horizontal: false, vertical: true)
                    Button("Copy Homebrew Command") {
                        NSPasteboard.general.clearContents()
                        NSPasteboard.general.setString(brewCommand, forType: .string)
                    }
                    .controlSize(.small)
                }
            }
            .padding(10)
            .background(RoundedRectangle(cornerRadius: 12, style: .continuous).fill(t.warn.opacity(0.12)))
        }
    }
}

struct AccountCard: View {
    @EnvironmentObject var model: AppModel
    @Environment(\.qdl) private var t

    var body: some View {
        let ok = model.hasCredentials
        Button {
            model.showAccount = true
        } label: {
            HStack(spacing: 10) {
                Image(systemName: ok ? "person.crop.circle.badge.checkmark" : "person.crop.circle.badge.exclamationmark")
                    .font(.system(size: 20))
                    .foregroundStyle(ok ? t.ok : t.warn)
                VStack(alignment: .leading, spacing: 1) {
                    Text(ok ? "Qobuz account" : "Add Qobuz account").font(.system(size: 13, weight: .medium))
                    if ok {
                        Text(model.authMethod == .token ? "User \(model.accountID)" : model.accountID)
                            .font(.system(size: 11.5))
                            .foregroundStyle(t.sub)
                            .lineLimit(1)
                    }
                }
                Spacer(minLength: 0)
            }
            .padding(10)
            .background(RoundedRectangle(cornerRadius: 14, style: .continuous).fill(t.control))
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
    }
}

// MARK: - Browse

struct BrowseView: View {
    @EnvironmentObject var model: AppModel
    @Environment(\.qdl) private var t

    var body: some View {
        switch model.previewState {
        case .idle:
            EmptyBrowse()
        case .loading(let message):
            VStack(spacing: 14) {
                ProgressView().controlSize(.large)
                Text(message).foregroundStyle(t.sub)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        case .failed(let message):
            VStack(spacing: 12) {
                Image(systemName: "exclamationmark.triangle")
                    .font(.system(size: 34))
                    .foregroundStyle(t.warn)
                Text("Couldn't open that link").font(.system(size: 20, weight: .semibold))
                Text(message)
                    .foregroundStyle(t.sub)
                    .multilineTextAlignment(.center)
                    .frame(maxWidth: 460)
                HStack {
                    Button("Try Again") { model.openLink() }
                    Button("Account…") { model.showAccount = true }
                    Button("Show Activity") { model.go(.downloads); model.showLog = true }
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        case .ready:
            if let p = model.preview {
                AlbumView(preview: p)
            } else {
                EmptyBrowse()
            }
        }
    }
}

struct EmptyBrowse: View {
    @EnvironmentObject var model: AppModel
    @Environment(\.qdl) private var t

    var body: some View {
        VStack(spacing: 16) {
            Image(systemName: "music.note.list")
                .font(.system(size: 54, weight: .light))
                .foregroundStyle(t.accent)
            Text("Open an album").font(.system(size: 26, weight: .bold))
            Text("Pick something in the Store, or paste a Qobuz link. It opens here with its cover and tracklist, so you can choose exactly what to download.")
                .foregroundStyle(t.sub)
                .multilineTextAlignment(.center)
                .frame(maxWidth: 440)
            HStack(spacing: 10) {
                AccentButton(title: "Go to Store", icon: "bag") { model.go(.store) }
                AccentButton(title: "Paste Link", icon: "doc.on.clipboard") { model.pasteAndOpen() }
            }
            Text("Tip: ⇧⌘V pastes and opens a link from anywhere").font(.system(size: 12)).foregroundStyle(t.faint)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }
}

struct AlbumView: View {
    let preview: Preview

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 26) {
                AlbumHeader(preview: preview)
                InLibraryBanner(preview: preview)
                if preview.isWholeOnly {
                    WholeOnlyNote(preview: preview)
                } else {
                    TrackList(preview: preview)
                }
            }
            .padding(.horizontal, 24)
            .padding(.top, 18)
            .padding(.bottom, 130)
        }
        .overlay(alignment: .bottom) {
            DownloadBar()
                .padding(.horizontal, 12)
                .padding(.bottom, 4)
        }
    }
}

struct AlbumHeader: View {
    @EnvironmentObject var model: AppModel
    @EnvironmentObject var catalog: CatalogModel
    @Environment(\.qdl) private var t
    let preview: Preview

    private var meta: String {
        var parts: [String] = []
        if let y = preview.year { parts.append(y) }
        if let g = preview.genre { parts.append(g) }
        if !preview.tracks.isEmpty {
            parts.append("\(preview.tracks.count) track\(preview.tracks.count == 1 ? "" : "s")")
            parts.append("\(max(1, preview.totalSeconds / 60)) min")
        }
        if let l = preview.label { parts.append(l) }
        return parts.joined(separator: " · ")
    }

    private var rateText: String {
        let r = preview.maxSampleRate
        return r.rounded() == r ? String(Int(r)) : String(format: "%.1f", r)
    }

    var body: some View {
        HStack(alignment: .bottom, spacing: 26) {
            CoverView(image: model.cover, url: preview.coverURL, size: 220, radius: 14)
                .shadow(color: .black.opacity(0.4), radius: 24, y: 14)
            VStack(alignment: .leading, spacing: 9) {
                Text(preview.kind.uppercased())
                    .font(.system(size: 11.5, weight: .semibold))
                    .foregroundStyle(t.sub)
                Text(preview.title)
                    .font(.system(size: 38, weight: .bold))
                    .lineLimit(3)
                Text(preview.artist)
                    .font(.system(size: 18, weight: .medium))
                    .foregroundStyle(t.accentText)
                if !meta.isEmpty {
                    Text(meta).font(.system(size: 13)).foregroundStyle(t.sub)
                }
                HStack(spacing: 8) {
                    if preview.maxBitDepth > 0 {
                        Badge(text: (preview.maxBitDepth >= 24 ? "Hi-Res · " : "CD · ") + "\(preview.maxBitDepth)-bit / \(rateText) kHz", gold: preview.maxBitDepth >= 24)
                    }
                    if preview.discCount > 1 {
                        Badge(text: "\(preview.discCount) discs")
                    }
                }
                .padding(.top, 2)
                HStack(spacing: 8) {
                    if let artistID = preview.artistID {
                        Button {
