import Foundation

/// Talks to Qobuz through the installed streamrip, so it shares the same login,
/// app ID and secrets as the downloads.
enum Metadata {
    /// A small long-running Python helper. It logs in once, then answers JSON requests
    /// on stdin with JSON lines on stdout ("QDLJSON:{...}").
    static let bridgeScript = """
    import asyncio, json, sys

    def emit(obj):
        sys.stdout.write("QDLJSON:" + json.dumps(obj) + "\\n")
        sys.stdout.flush()

    async def api(client, ep, params):
        status, resp = await client._api_request(ep, params)
        if status != 200:
            raise RuntimeError("Qobuz " + ep + " returned " + str(status) + ": " + str(resp)[:200])
        return resp

    async def handle(client, req):
        rid = req.get("id")
        cmd = req.get("cmd")
        a = req.get("args") or {}
        try:
            if cmd == "meta":
                data = await client.get_metadata(str(a["id"]), a["kind"])
            elif cmd == "search":
                q = a["q"]
                lim = int(a.get("limit", 24))
                try:
                    data = await api(client, "catalog/search", {"query": q, "limit": lim})
                except Exception:
                    data = {}
                    for t in ("album", "track", "artist", "playlist"):
                        try:
                            r = await api(client, t + "/search", {"query": q, "limit": lim})
                            data[t + "s"] = r.get(t + "s", {})
                        except Exception:
                            pass
            elif cmd == "featured":
                p = {"type": a["type"], "limit": int(a.get("limit", 24))}
                if a.get("genre"):
                    p["genre_ids"] = str(a["genre"])
                data = await api(client, "album/getFeatured", p)
            elif cmd == "genres":
                data = await api(client, "genre/list", {})
            elif cmd == "favorites":
                data = await api(client, "favorite/getUserFavorites", {"limit": 500})
            elif cmd == "playlists":
                data = await api(client, "playlist/getUserPlaylists", {"limit": 500})
            elif cmd == "stream":
                secret = getattr(client, "secret", None)
                status, resp = await client._request_file_url(str(a["id"]), int(a.get("quality", 1)), secret)
                data = {"url": resp.get("url"), "restrictions": resp.get("restrictions")}
            elif cmd == "ping":
                data = {}
            else:
                raise ValueError("Unknown command " + str(cmd))
            emit({"id": rid, "ok": True, "data": data})
        except Exception as e:
            emit({"id": rid, "ok": False, "error": type(e).__name__ + ": " + str(e)})

    async def main():
        from streamrip.config import Config
        try:
            from streamrip.client import QobuzClient
        except ImportError:
            from streamrip.client.qobuz import QobuzClient
        client = QobuzClient(Config(sys.argv[1]))
        try:
            await client.login()
        except Exception as e:
            emit({"id": 0, "ok": False, "error": type(e).__name__ + ": " + str(e)})
            return
        emit({"id": 0, "ok": True, "data": {"ready": True}})
        loop = asyncio.get_running_loop()
        reader = asyncio.StreamReader()
        protocol = asyncio.StreamReaderProtocol(reader)
        await loop.connect_read_pipe(lambda: protocol, sys.stdin)
        tasks = set()
        while True:
            line = await reader.readline()
            if not line:
                break
            try:
                req = json.loads(line)
            except Exception:
                continue
            t = asyncio.create_task(handle(client, req))
            tasks.add(t)
            t.add_done_callback(tasks.discard)
        session = getattr(client, "session", None)
        if session is not None:
            try:
                await session.close()
            except Exception:
                pass

    asyncio.run(main())
    """

    /// The Python inside streamrip's own environment (pipx), found from the rip command.
    static func streamripPython() -> String? {
        guard let rip = Shell.which("rip") else { return nil }
        let resolved = URL(fileURLWithPath: rip).resolvingSymlinksInPath()
        let sibling = resolved.deletingLastPathComponent().appendingPathComponent("python").path
        if FileManager.default.isExecutableFile(atPath: sibling) { return sibling }
        if let text = try? String(contentsOfFile: resolved.path, encoding: .utf8), text.hasPrefix("#!"),
           let first = text.split(separator: "\n").first {
            let interpreter = String(first.dropFirst(2)).trimmed
            if FileManager.default.isExecutableFile(atPath: interpreter) { return interpreter }
        }
        return nil
    }

    static func writeBridge() -> URL {
        let url = Paths.support.appendingPathComponent("qdl_bridge.py")
        try? bridgeScript.write(to: url, atomically: true, encoding: .utf8)
        return url
    }

    // MARK: Parsing Qobuz JSON

    static func int(_ v: Any?) -> Int {
        if let i = v as? Int { return i }
        if let d = v as? Double { return Int(d) }
        if let s = v as? String { return Int(s) ?? Int(Double(s) ?? 0) }
        return 0
    }

    static func double(_ v: Any?) -> Double {
        if let d = v as? Double { return d }
        if let i = v as? Int { return Double(i) }
        if let s = v as? String { return Double(s) ?? 0 }
        return 0
    }

    static func string(_ v: Any?) -> String? {
        if let s = v as? String, !s.isEmpty { return s }
        if let i = v as? Int { return String(i) }
        return nil
    }

    static func name(_ v: Any?) -> String? {
        (v as? [String: Any]).flatMap { string($0["name"]) }
    }

    static func image(_ v: Any?) -> URL? {
        guard let img = v as? [String: Any] else { return nil }
        for key in ["large", "extralarge", "mega", "medium", "small", "thumbnail"] {
            if let s = string(img[key]), let u = URL(string: s) { return u }
        }
        return nil
    }

    static func cover(_ album: [String: Any]?) -> URL? {
        image(album?["image"])
    }

    static func items(_ v: Any?) -> [[String: Any]] {
        ((v as? [String: Any])?["items"] as? [[String: Any]]) ?? []
    }

    static func track(_ d: [String: Any], albumArtist: String?, number: Int? = nil) -> PreviewTrack? {
        guard let id = string(d["id"]) else { return nil }
        var title = string(d["title"]) ?? "Untitled"
        if let version = string(d["version"]), !title.lowercased().contains(version.lowercased()) {
            title += " (\(version))"
        }
        let album = d["album"] as? [String: Any]
        let performer = name(d["performer"]) ?? name(album?["artist"])
        return PreviewTrack(
            id: id,
            number: number ?? int(d["track_number"]),
            disc: number == nil ? max(1, int(d["media_number"])) : 1,
            title: title,
            artist: performer == albumArtist ? nil : performer,
            duration: int(d["duration"]),
            bitDepth: int(d["maximum_bit_depth"]),
            sampleRate: double(d["maximum_sampling_rate"]),
            streamable: (d["streamable"] as? Bool) ?? true,
            explicit: (d["parental_warning"] as? Bool) ?? false,
            performers: string(d["performers"]),
            coverURL: cover(album),
            album: string(album?["title"])
        )
    }

    static func booklets(_ json: [String: Any]) -> [Booklet] {
        let goodies = (json["goodies"] as? [[String: Any]]) ?? []
        return goodies.compactMap { g in
            guard let s = string(g["url"]) ?? string(g["original_url"]), let u = URL(string: s) else { return nil }
            return Booklet(name: string(g["name"]) ?? "Booklet", url: u)
        }
    }

    static func preview(from json: [String: Any], link: QobuzLink) -> Preview? {
        switch link.kind {
        case "album":
            let artist = name(json["artist"]) ?? "Unknown artist"
            let tracks = items(json["tracks"]).compactMap { track($0, albumArtist: artist) }
            var title = string(json["title"]) ?? "Untitled album"
            if let version = string(json["version"]) { title += " (\(version))" }
            return Preview(
                kind: "album", id: link.id, link: link.url, title: title, artist: artist,
                year: string(json["release_date_original"]).map { String($0.prefix(4)) },
                genre: name(json["genre"]), label: name(json["label"]), coverURL: cover(json),
                maxBitDepth: int(json["maximum_bit_depth"]), maxSampleRate: double(json["maximum_sampling_rate"]),
                tracks: tracks, isWholeOnly: false, booklets: booklets(json),
                artistID: (json["artist"] as? [String: Any]).flatMap { string($0["id"]) })
        case "track":
            let album = json["album"] as? [String: Any]
            let artist = name(json["performer"]) ?? name(album?["artist"]) ?? "Unknown artist"
            guard let t = track(json, albumArtist: artist) else { return nil }
            return Preview(
                kind: "track", id: link.id, link: link.url, title: t.title, artist: artist,
                year: string(album?["release_date_original"]).map { String($0.prefix(4)) },
                genre: name(album?["genre"]), label: name(album?["label"]), coverURL: cover(album),
                maxBitDepth: t.bitDepth, maxSampleRate: t.sampleRate, tracks: [t], isWholeOnly: false,
                booklets: [], artistID: (album?["artist"] as? [String: Any]).flatMap { string($0["id"]) })
        case "playlist":
            let tracks = items(json["tracks"]).enumerated().compactMap { i, d in
                track(d, albumArtist: nil, number: i + 1)
            }
            let images = (json["images300"] as? [String]) ?? (json["images"] as? [String]) ?? (json["images150"] as? [String]) ?? []
            return Preview(
                kind: "playlist", id: link.id, link: link.url,
                title: string(json["name"]) ?? "Playlist",
                artist: name(json["owner"]) ?? "Playlist",
                year: nil, genre: nil, label: nil,
                coverURL: images.first.flatMap { URL(string: $0) } ?? tracks.first?.coverURL,
                maxBitDepth: tracks.map(\.bitDepth).max() ?? 0,
                maxSampleRate: tracks.map(\.sampleRate).max() ?? 0,
                tracks: tracks, isWholeOnly: false, booklets: [], artistID: nil)
        default:
            return nil
        }
    }

    /// Rough size in MB per minute for a quality / format, capped by what the release offers.
    static func megabytesPerMinute(quality: AudioQuality, format: OutputFormat, preview: Preview) -> Double {
        if format == .aac { return 1.9 }
        if format == .mp3 || quality == .mp3 { return 2.4 }
        let effective = min(quality.rawValue, preview.bestQuality.rawValue)
        let depth: Double
        let rate: Double
        switch effective {
        case 2: depth = 16; rate = 44.1
        case 3: depth = 24; rate = min(96, max(44.1, preview.maxSampleRate))
        default: depth = 24; rate = max(44.1, preview.maxSampleRate)
        }
        // WAV is raw PCM; FLAC is roughly 60% of it.
        let kbps = depth * rate * 2 * (format == .wav ? 1.0 : 0.6)
        return kbps * 60 / 8 / 1000
    }

    /// "Name, Role, Role - Name, Role" → [(name, roles)]
    static func credits(_ performers: String?) -> [(String, String)] {
        guard let p = performers else { return [] }
        return p.components(separatedBy: " - ").compactMap { chunk in
            let parts = chunk.components(separatedBy: ",").map { $0.trimmed }.filter { !$0.isEmpty }
            guard let first = parts.first else { return nil }
            return (first, parts.dropFirst().joined(separator: ", "))
        }
    }
}

