import SwiftUI
import AppKit
import CoreImage

// MARK: - Choices

enum ThemeChoice: String, CaseIterable, Identifiable {
    case auto, light, dark
    var id: String { rawValue }
    var label: String { rawValue.capitalized }
    var colorScheme: ColorScheme? {
        switch self {
        case .auto: return nil
        case .light: return .light
        case .dark: return .dark
        }
    }
}

enum GlassStyle: String, CaseIterable, Identifiable {
    case tinted, clear
    var id: String { rawValue }
    var label: String { rawValue.capitalized }
}

enum Density: String, CaseIterable, Identifiable {
    case comfortable, compact
    var id: String { rawValue }
    var label: String { rawValue.capitalized }
    var rowHeight: CGFloat { self == .compact ? 34 : 44 }
}

enum AccentChoice: String, CaseIterable, Identifiable {
    case blue, purple, pink, orange, green, graphite, match
    var id: String { rawValue }
    var label: String { self == .match ? "Match background" : rawValue.capitalized }
}

enum BackgroundChoice: String, CaseIterable, Identifiable {
    case album, neutral, amber, ember, dusk, ocean, olive, violet, jade, silver
    var id: String { rawValue }
    var label: String {
        switch self {
        case .album: return "Album colours"
        case .neutral: return "Neutral"
        default: return Palettes.all[self]?.name ?? rawValue.capitalized
        }
    }
}

// MARK: - Colours

extension Color {
    init(hex: UInt32, opacity: Double = 1) {
        self.init(.sRGB,
                  red: Double((hex >> 16) & 0xFF) / 255,
                  green: Double((hex >> 8) & 0xFF) / 255,
                  blue: Double(hex & 0xFF) / 255,
                  opacity: opacity)
    }
}

extension NSColor {
    func tuned(saturation sat: CGFloat, brightness b: CGFloat) -> NSColor {
        let c = usingColorSpace(.sRGB) ?? self
        var h: CGFloat = 0, s: CGFloat = 0, v: CGFloat = 0, a: CGFloat = 0
        c.getHue(&h, saturation: &s, brightness: &v, alpha: &a)
        return NSColor(hue: h, saturation: min(1, max(0, sat)), brightness: min(1, max(0, b)), alpha: 1)
    }

    var hsb: (h: CGFloat, s: CGFloat, b: CGFloat) {
        let c = usingColorSpace(.sRGB) ?? self
        var h: CGFloat = 0, s: CGFloat = 0, v: CGFloat = 0, a: CGFloat = 0
        c.getHue(&h, saturation: &s, brightness: &v, alpha: &a)
        return (h, s, v)
    }

    var luminance: CGFloat {
        let c = usingColorSpace(.sRGB) ?? self
        func lin(_ x: CGFloat) -> CGFloat { x <= 0.03928 ? x / 12.92 : pow((x + 0.055) / 1.055, 2.4) }
        return 0.2126 * lin(c.redComponent) + 0.7152 * lin(c.greenComponent) + 0.0722 * lin(c.blueComponent)
    }
}

struct Palette {
    let name: String
    let soft: Color, golden: Color, sunset: Color, sienna: Color, deep: Color, espresso: Color, hi: Color

    init(_ name: String, _ soft: UInt32, _ golden: UInt32, _ sunset: UInt32, _ sienna: UInt32,
         _ deep: UInt32, _ espresso: UInt32, _ hi: UInt32) {
        self.name = name
        self.soft = Color(hex: soft); self.golden = Color(hex: golden); self.sunset = Color(hex: sunset)
        self.sienna = Color(hex: sienna); self.deep = Color(hex: deep); self.espresso = Color(hex: espresso)
        self.hi = Color(hex: hi)
    }

    var gradient: LinearGradient {
        LinearGradient(colors: [golden, sunset, sienna, deep], startPoint: .topLeading, endPoint: .bottomTrailing)
    }
}

/// The eight palettes from hishamalfar.com.
