struct SystemAccent {
    let dark: Color, light: Color, button: Color, buttonText: Color, textDark: Color, textLight: Color

    static let all: [AccentChoice: SystemAccent] = [
        .blue: SystemAccent(dark: Color(hex: 0x0A84FF), light: Color(hex: 0x007AFF), button: Color(hex: 0x0066D6), buttonText: .white, textDark: Color(hex: 0x64A8FF), textLight: Color(hex: 0x0060C7)),
        .purple: SystemAccent(dark: Color(hex: 0xBF5AF2), light: Color(hex: 0xAF52DE), button: Color(hex: 0x8E3BBF), buttonText: .white, textDark: Color(hex: 0xD18CF5), textLight: Color(hex: 0x8A3DB5)),
        .pink: SystemAccent(dark: Color(hex: 0xFF375F), light: Color(hex: 0xFF2D55), button: Color(hex: 0xD6204A), buttonText: .white, textDark: Color(hex: 0xFF7A93), textLight: Color(hex: 0xC4173F)),
        .orange: SystemAccent(dark: Color(hex: 0xFF9F0A), light: Color(hex: 0xFF9500), button: Color(hex: 0xFF9F0A), buttonText: Color(hex: 0x1D1D1F), textDark: Color(hex: 0xFFB547), textLight: Color(hex: 0xB35C00)),
        .green: SystemAccent(dark: Color(hex: 0x30D158), light: Color(hex: 0x34C759), button: Color(hex: 0x30D158), buttonText: Color(hex: 0x0B1F10), textDark: Color(hex: 0x5EE07D), textLight: Color(hex: 0x1E7A35)),
        .graphite: SystemAccent(dark: Color(hex: 0x98989D), light: Color(hex: 0x8E8E93), button: Color(hex: 0x636366), buttonText: .white, textDark: Color(hex: 0xC7C7CC), textLight: Color(hex: 0x48484A)),
    ]
}

// MARK: - Theme tokens

struct Theme {
    var isDark = true
    var reduce = false
    var clear = false

    var text = Color(hex: 0xF5F5F7)
    var sub = Color(red: 235 / 255, green: 235 / 255, blue: 245 / 255).opacity(0.72)
    var faint = Color(red: 235 / 255, green: 235 / 255, blue: 245 / 255).opacity(0.55)

    var base = Color(hex: 0x141419)
    var blobs: [Color] = [Color(hex: 0x1D4E6B), Color(hex: 0xF2A65A), Color(hex: 0x2E6E86), Color(hex: 0x9CC7D6)]
    var blobOpacity = 0.55
    var softOpacity = 0.22

    var tint = Color(hex: 0x222228, opacity: 0.35)
    var tintStrong = Color(hex: 0x26262C, opacity: 0.5)
    var solid = Color(hex: 0x26262B)
    var border = Color.white.opacity(0.16)
    var hairline = Color.white.opacity(0.10)
    var control = Color.white.opacity(0.08)
    var segOn = Color.white.opacity(0.20)

    var accent = Color(hex: 0x0A84FF)
    var accentText = Color(hex: 0x64A8FF)
    var button = Color(hex: 0x0066D6)
    var buttonText = Color.white
    var accentSoft = Color(hex: 0x0A84FF, opacity: 0.2)

    var badgeFill = Color(hex: 0xF5C451, opacity: 0.14)
    var badgeText = Color(hex: 0xF5C451)
    var ok = Color(hex: 0x5EE07D)
    var warn = Color(hex: 0xFF9F6B)

    var material: Material { clear ? .ultraThinMaterial : .regularMaterial }
}

struct ThemeKey: EnvironmentKey {
    static let defaultValue = Theme()
}

extension EnvironmentValues {
    var qdl: Theme {
        get { self[ThemeKey.self] }
        set { self[ThemeKey.self] = newValue }
    }
}

enum ThemeBuilder {
    static func make(isDark: Bool, glass: GlassStyle, reduce: Bool, accent: AccentChoice,
                     background: BackgroundChoice, albumColors: [NSColor]) -> Theme {
        var t = Theme()
        t.isDark = isDark
        t.reduce = reduce
        t.clear = glass == .clear

        if isDark {
            t.text = Color(hex: 0xF5F5F7)
            t.sub = Color(red: 235 / 255, green: 235 / 255, blue: 245 / 255).opacity(0.72)
            t.faint = Color(red: 235 / 255, green: 235 / 255, blue: 245 / 255).opacity(0.55)
            t.base = Color(hex: 0x141419)
            t.tint = glass == .clear ? Color.white.opacity(0.03) : Color(hex: 0x222228, opacity: 0.38)
            t.tintStrong = glass == .clear ? Color.white.opacity(0.05) : Color(hex: 0x26262C, opacity: 0.52)
            t.solid = Color(hex: 0x26262B)
            t.border = Color.white.opacity(reduce ? 0.10 : 0.16)
            t.hairline = Color.white.opacity(0.10)
            t.control = Color.white.opacity(0.08)
            t.segOn = Color.white.opacity(0.20)
            t.badgeFill = Color(hex: 0xF5C451, opacity: 0.14)
            t.badgeText = Color(hex: 0xF5C451)
            t.ok = Color(hex: 0x5EE07D)
            t.warn = Color(hex: 0xFF9F6B)
        } else {
            t.text = Color(hex: 0x1D1D1F)
            t.sub = Color(red: 60 / 255, green: 60 / 255, blue: 67 / 255).opacity(0.82)
            t.faint = Color(red: 60 / 255, green: 60 / 255, blue: 67 / 255).opacity(0.68)
            t.base = Color(hex: 0xEEF0F5)
            t.tint = glass == .clear ? Color.white.opacity(0.10) : Color.white.opacity(0.42)
            t.tintStrong = glass == .clear ? Color.white.opacity(0.18) : Color.white.opacity(0.55)
            t.solid = .white
            t.border = reduce ? Color.black.opacity(0.08) : Color.white.opacity(0.8)
            t.hairline = Color.black.opacity(0.08)
            t.control = Color.black.opacity(0.05)
            t.segOn = Color.white.opacity(0.96)
            t.badgeFill = Color(hex: 0xC48C14, opacity: 0.12)
            t.badgeText = Color(hex: 0x7A5300)
            t.ok = Color(hex: 0x1E7A35)
            t.warn = Color(hex: 0xB3401A)
        }

        // Background
        var matchDark: (Color, Color, Color, Color)? = nil   // accent, text, button, buttonText
        var matchLight: (Color, Color, Color, Color)? = nil
        switch background {
        case .neutral:
            t.blobs = isDark
                ? [Color(hex: 0x2B2D42), Color(hex: 0x3A3550), Color(hex: 0x24324A), Color(hex: 0x2B2D42)]
                : [Color(hex: 0xC9D6F0), Color(hex: 0xE6D9F2), Color(hex: 0xD3E7EE), Color(hex: 0xF0E6F6)]
            t.blobOpacity = isDark ? 0.6 : 0.7
            t.softOpacity = isDark ? 0.3 : 0.5
        case .album:
            if albumColors.count >= 4 {
                let tunedBlobs = albumColors.prefix(4).map { c -> Color in
                    let v = c.hsb
                    return Color(nsColor: c.tuned(saturation: v.s * 1.25, brightness: isDark ? max(0.35, min(0.85, v.b)) : max(0.6, v.b)))
                }
                t.blobs = Array(tunedBlobs)
                let vivid = albumColors.max(by: { $0.hsb.s * $0.hsb.b < $1.hsb.s * $1.hsb.b }) ?? albumColors[0]
                let s = max(0.45, vivid.hsb.s)
                let bright = vivid.tuned(saturation: s, brightness: 0.88)
                let darkish = vivid.tuned(saturation: s, brightness: 0.42)
                let brightText: Color = bright.luminance > 0.4 ? Color(hex: 0x111111) : .white
                matchDark = (Color(nsColor: bright), Color(nsColor: bright), Color(nsColor: bright), brightText)
                matchLight = (Color(nsColor: darkish), Color(nsColor: darkish), Color(nsColor: darkish), .white)
            } else {
                let p = Palettes.albumFallback
                t.blobs = [p.sienna, p.golden, p.sunset, p.soft]
                matchDark = (p.golden, p.golden, p.golden, p.espresso)
                matchLight = (p.sienna, p.deep, p.deep, .white)
            }
            t.blobOpacity = isDark ? 0.55 : 0.42
            t.softOpacity = isDark ? 0.22 : 0.5
        default:
            if let p = Palettes.all[background] {
                t.base = isDark ? p.espresso : p.hi
                t.blobs = [p.sunset, p.golden, p.sienna, p.soft]
                t.blobOpacity = isDark ? 0.55 : 0.45
                t.softOpacity = isDark ? 0.22 : 0.5
                matchDark = (p.golden, p.golden, p.golden, p.espresso)
                matchLight = (p.sienna, p.deep, p.deep, .white)
            }
        }

        // Accent
        if accent == .match, let m = (isDark ? matchDark : matchLight) {
            t.accent = m.0; t.accentText = m.1; t.button = m.2; t.buttonText = m.3
        } else {
            let a = SystemAccent.all[accent == .match ? .graphite : accent] ?? SystemAccent.all[.blue]!
            t.accent = isDark ? a.dark : a.light
            t.accentText = isDark ? a.textDark : a.textLight
            t.button = a.button
            t.buttonText = a.buttonText
        }
        t.accentSoft = t.accent.opacity(isDark ? 0.20 : 0.14)
        return t
    }
}

