// MARK: - Reading colours from a cover

enum CoverColors {
    /// Average colours of four regions of the image: top-left, centre, bottom-right, top-right.
    static func extract(from data: Data) -> [NSColor] {
        guard let image = CIImage(data: data) else { return [] }
        let e = image.extent
        let ctx = CIContext(options: [.workingColorSpace: NSNull()])
        let half = CGSize(width: e.width / 2, height: e.height / 2)
        let regions = [
            CGRect(x: e.minX, y: e.midY, width: half.width, height: half.height),
            CGRect(x: e.minX + e.width / 4, y: e.minY + e.height / 4, width: half.width, height: half.height),
            CGRect(x: e.midX, y: e.minY, width: half.width, height: half.height),
            CGRect(x: e.midX, y: e.midY, width: half.width, height: half.height),
        ]
        var out: [NSColor] = []
        for r in regions {
            guard let f = CIFilter(name: "CIAreaAverage",
                                   parameters: [kCIInputImageKey: image, kCIInputExtentKey: CIVector(cgRect: r)]),
                  let avg = f.outputImage else { continue }
            var px = [UInt8](repeating: 0, count: 4)
            ctx.render(avg, toBitmap: &px, rowBytes: 4, bounds: CGRect(x: 0, y: 0, width: 1, height: 1),
                       format: .RGBA8, colorSpace: nil)
            out.append(NSColor(srgbRed: CGFloat(px[0]) / 255, green: CGFloat(px[1]) / 255,
                               blue: CGFloat(px[2]) / 255, alpha: 1))
        }
        return out
    }
}

