import Foundation

/// Keeps one logged-in streamrip session alive and sends it JSON requests.
@MainActor
final class QobuzBridge {
    struct BridgeError: LocalizedError {
        let message: String
        var errorDescription: String? { message }
    }

    /// Writes a config with the account in it and returns its path (nil = no account).
    var prepare: (() async -> String?)?
    /// Called once the helper has logged in (used to wipe the token from disk again).
    var afterLogin: (() -> Void)?
    /// Lines the helper printed that weren't answers (warnings, tracebacks).
    var onLog: ((String) -> Void)?

    private var process: Process?
    private var input: FileHandle?
    private var pending: [Int: CheckedContinuation<Any, Error>] = [:]
    private var nextID = 1
    private var ready = false
    private var startTask: Task<Void, Error>?
    private var startWaiter: CheckedContinuation<Void, Error>?

    func request(_ cmd: String, _ args: [String: Any] = [:]) async throws -> Any {
        try await ensureStarted()
        let id = nextID
        nextID += 1
        let payload: [String: Any] = ["id": id, "cmd": cmd, "args": args]
        let data = try JSONSerialization.data(withJSONObject: payload)
        return try await withCheckedThrowingContinuation { cont in
            pending[id] = cont
            input?.write(data + Data("\n".utf8))
        }
    }

    /// Same as request, but expects a JSON object back.
    func object(_ cmd: String, _ args: [String: Any] = [:]) async throws -> [String: Any] {
        let any = try await request(cmd, args)
        guard let dict = any as? [String: Any] else {
            throw BridgeError(message: "Qobuz sent back something unexpected.")
        }
        return dict
    }

    func stop() {
        if let p = process, p.isRunning { p.terminate() }
        process = nil
        input = nil
        ready = false
    }

    private func ensureStarted() async throws {
        if ready, let p = process, p.isRunning { return }
        if let t = startTask {
            try await t.value
            return
        }
        let t = Task<Void, Error> { @MainActor in try await self.start() }
        startTask = t
        do {
            try await t.value
            startTask = nil
        } catch {
            startTask = nil
            throw error
        }
    }

    private func start() async throws {
        stop()
        guard let python = Metadata.streamripPython() else {
            throw BridgeError(message: "Couldn't find streamrip's Python. Try QDL → Update Download Engine.")
        }
        guard let config = await prepare?() else {
            throw BridgeError(message: "Add your Qobuz account first.")
        }
        let script = Metadata.writeBridge()
        let p = Process()
        p.executableURL = URL(fileURLWithPath: python)
        p.arguments = [script.path, config]
        p.environment = Shell.environment
        p.currentDirectoryURL = Paths.support
        let inPipe = Pipe()
        let outPipe = Pipe()
        p.standardInput = inPipe
        p.standardOutput = outPipe
        p.standardError = outPipe

        let splitter = LineSplitter { [weak self] line in
            Task { @MainActor in self?.handle(line) }
        }
        outPipe.fileHandleForReading.readabilityHandler = { h in
            let d = h.availableData
            if d.isEmpty { h.readabilityHandler = nil } else { splitter.feed(d) }
        }
        p.terminationHandler = { [weak self] _ in
            Task { @MainActor in self?.terminated() }
        }
        try p.run()
        process = p
        input = inPipe.fileHandleForWriting
        try await withCheckedThrowingContinuation { (c: CheckedContinuation<Void, Error>) in
            startWaiter = c
        }
    }

    private func handle(_ line: String) {
        guard line.hasPrefix("QDLJSON:"),
              let data = String(line.dropFirst(8)).data(using: .utf8),
              let obj = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any] else {
            onLog?(line)
            return
        }
        let id = Metadata.int(obj["id"])
        let ok = (obj["ok"] as? Bool) ?? false
        if id == 0 {
            if ok {
                ready = true
                startWaiter?.resume()
            } else {
                let msg = Metadata.string(obj["error"]) ?? "Login failed"
                startWaiter?.resume(throwing: BridgeError(message: Self.friendly(msg)))
            }
            startWaiter = nil
            afterLogin?()
            return
        }
        guard let cont = pending.removeValue(forKey: id) else { return }
        if ok {
            cont.resume(returning: obj["data"] ?? NSNull())
        } else {
            let msg = Metadata.string(obj["error"]) ?? "Unknown error"
            cont.resume(throwing: BridgeError(message: Self.friendly(msg)))
        }
    }

    private func terminated() {
        ready = false
        process = nil
        input = nil
        startWaiter?.resume(throwing: BridgeError(message: "The Qobuz helper stopped. Show Activity for details."))
        startWaiter = nil
        let waiting = pending
        pending.removeAll()
        for (_, c) in waiting {
            c.resume(throwing: BridgeError(message: "The Qobuz helper stopped. Try again."))
        }
    }

    static func friendly(_ msg: String) -> String {
        let l = msg.lowercased()
        if l.contains("authentication") || l.contains("invalid") && l.contains("token") || l.contains("401") {
            return "Qobuz rejected the login. Your token may have expired — update it in Account."
        }
        if l.contains("ineligible") {
            return "This Qobuz account can't stream or download (free or expired subscription?)."
        }
        return msg
    }
}

