import SwiftUI
import AVFoundation

struct NowPlaying: Equatable {
    let id: String
    let title: String
    let artist: String
    let coverURL: URL?
    let duration: Double
}

/// Streams a track from Qobuz (MP3 320) so you can check it before downloading.
@MainActor
final class AudioPlayer: ObservableObject {
    unowned let app: AppModel

    @Published var current: NowPlaying?
    @Published var isPlaying = false
    @Published var position: Double = 0
    @Published var loadingID: String?
    @Published var error: String?

    private var player: AVPlayer?
    private var timeObserver: Any?
    private var endObserver: NSObjectProtocol?

    init(app: AppModel) { self.app = app }

    var progress: Double {
        guard let d = current?.duration, d > 0 else { return 0 }
        return min(1, position / d)
    }

    func isCurrent(_ id: String) -> Bool { current?.id == id }

    func play(id: String, title: String, artist: String, coverURL: URL?, duration: Int) {
        if current?.id == id {
            toggle()
            return
        }
        loadingID = id
        error = nil
        Task {
            do {
                let r = try await app.bridge.object("stream", ["id": id, "quality": 1])
                guard let s = Metadata.string(r["url"]), let url = URL(string: s) else {
                    var reason = "This track can't be streamed."
                    if let list = r["restrictions"] as? [[String: Any]], let code = Metadata.string(list.first?["code"]) {
                        reason = "Can't stream: " + code
                    }
                    throw QobuzBridge.BridgeError(message: reason)
                }
                guard loadingID == id else { return }
                start(url: url, item: NowPlaying(id: id, title: title, artist: artist, coverURL: coverURL,
                                                 duration: Double(duration)))
            } catch {
                self.error = error.localizedDescription
                app.appendLog("Preview: \(error.localizedDescription)", isError: true)
            }
            if loadingID == id { loadingID = nil }
        }
    }

    private func start(url: URL, item: NowPlaying) {
        teardown()
        let playerItem = AVPlayerItem(url: url)
        let p = AVPlayer(playerItem: playerItem)
        player = p
        current = item
        position = 0
        timeObserver = p.addPeriodicTimeObserver(forInterval: CMTime(seconds: 0.5, preferredTimescale: 600),
                                                 queue: .main) { [weak self] t in
            let secs = t.seconds
            Task { @MainActor in self?.position = secs.isFinite ? secs : 0 }
        }
        endObserver = NotificationCenter.default.addObserver(forName: .AVPlayerItemDidPlayToEndTime,
                                                             object: playerItem, queue: .main) { [weak self] _ in
            Task { @MainActor in
                self?.isPlaying = false
                self?.position = 0
                self?.player?.seek(to: .zero)
            }
        }
        p.play()
        isPlaying = true
    }

    func toggle() {
        guard let p = player else { return }
        if isPlaying { p.pause() } else { p.play() }
        isPlaying.toggle()
    }

    func seek(to fraction: Double) {
        guard let p = player, let d = current?.duration, d > 0 else { return }
        let t = max(0, min(1, fraction)) * d
        position = t
        p.seek(to: CMTime(seconds: t, preferredTimescale: 600))
    }

    func stop() {
        teardown()
        current = nil
        isPlaying = false
        position = 0
    }

    private func teardown() {
        if let o = timeObserver { player?.removeTimeObserver(o) }
        timeObserver = nil
        if let e = endObserver { NotificationCenter.default.removeObserver(e) }
        endObserver = nil
        player?.pause()
        player = nil
    }
}

