import SwiftUI
import AppKit

/// The menu bar mini-QDL: quick search and download progress.
struct MenuBarPanel: View {
    @EnvironmentObject var model: AppModel
    @EnvironmentObject var updater: Updater
    @Environment(\.openWindow) private var openWindow
    @State private var query = ""

    private func showMain() {
        openWindow(id: "main")
        NSApp.activate(ignoringOtherApps: true)
    }

    private func status(_ job: DownloadJob) -> String {
        switch job.status {
        case .queued: return "Waiting"
        case .running:
            if job.tracks.isEmpty || job.wholeRelease { return "Downloading" }
            return "\(job.doneCount) of \(job.tracks.count)"
        case .done: return "Done"
        case .warning: return "Partly done"
        case .failed: return "Failed"
        case .cancelled: return "Stopped"
        }
    }

    var body: some View {
        let active = model.jobs.filter { !$0.status.isFinished }
        let finished = Array(model.jobs.filter { $0.status.isFinished }.suffix(3).reversed())
        VStack(alignment: .leading, spacing: 12) {
            HStack(spacing: 8) {
                Image(systemName: "waveform").foregroundStyle(.tint)
                Text("QDL").font(.headline)
                Spacer()
                if model.isRunning { ProgressView().controlSize(.small) }
            }

            TextField("Search Qobuz or paste a link", text: $query)
                .textFieldStyle(.roundedBorder)
                .onSubmit {
                    let q = query
                    query = ""
                    showMain()
                    model.linkField = q
                    model.submit(q)
                }

            Divider()

            if active.isEmpty {
                Text("Nothing downloading").font(.callout).foregroundStyle(.secondary)
            } else {
                ForEach(active.prefix(5)) { job in
                    VStack(alignment: .leading, spacing: 4) {
                        HStack {
                            Text(job.title).font(.callout.weight(.medium)).lineLimit(1)
                            Spacer()
                            Text(status(job)).font(.caption).foregroundStyle(.secondary)
                        }
                        if job.status == .running && (job.wholeRelease || job.tracks.isEmpty) {
                            ProgressView().progressViewStyle(.linear)
                        } else {
                            ProgressView(value: job.progress).progressViewStyle(.linear)
                        }
                    }
                }
                if model.isRunning {
                    Button("Stop Downloads") { model.stop() }
                }
            }

            if !finished.isEmpty {
                Text("RECENT").font(.caption2.weight(.semibold)).foregroundStyle(.secondary)
                ForEach(finished) { job in
                    HStack {
                        Image(systemName: job.status == .done ? "checkmark.circle.fill" : "exclamationmark.circle.fill")
                            .foregroundStyle(job.status == .done ? Color.green : Color.orange)
                        Text(job.title).font(.callout).lineLimit(1)
                        Spacer()
                        Text(status(job)).font(.caption).foregroundStyle(.secondary)
                    }
                }
            }

            if let r = updater.available {
                Divider()
                Button("Install update (build \(r.build))…") { Task { await updater.install() } }
            }

            Divider()
            HStack {
                Button("Open QDL") { showMain() }
                Button("Show in Finder") { model.revealFolder() }
                Spacer()
                Button("Quit") { NSApp.terminate(nil) }
            }
        }
        .padding(14)
        .frame(width: 320)
    }
}

