import SwiftUI
import AppKit

/// Checks the QDL GitHub repository for newer builds and installs them in place.
@MainActor
final class Updater: ObservableObject {
    struct Release: Equatable {
        let build: Int
        let tag: String
        let zipURL: URL
        let notes: String
    }

    enum State: Equatable {
        case idle, checking, upToDate, downloading, installing
        case failed(String)
    }

    static let repo = "hisham-alfar/QDL"

    @Published var available: Release?
    @Published var state: State = .idle
    @Published var lastChecked: Date?

    var currentBuild: Int {
        Int((Bundle.main.object(forInfoDictionaryKey: "CFBundleVersion") as? String) ?? "0") ?? 0
    }

    var currentVersion: String {
        (Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String) ?? "1.0"
    }

    func check(silent: Bool) async {
        if state == .downloading || state == .installing { return }
        state = .checking
        do {
            var req = URLRequest(url: URL(string: "https://api.github.com/repos/\(Self.repo)/releases/latest")!)
            req.setValue("application/vnd.github+json", forHTTPHeaderField: "Accept")
            req.setValue("QDL-macOS", forHTTPHeaderField: "User-Agent")
            let (data, response) = try await URLSession.shared.data(for: req)
            if let http = response as? HTTPURLResponse, http.statusCode == 404 {
                available = nil
                state = silent ? .idle : .upToDate
                return
            }
            guard let json = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any],
                  let tag = Metadata.string(json["tag_name"]) else {
                throw QobuzBridge.BridgeError(message: "GitHub sent an unexpected reply.")
            }
            let build = Int(tag.components(separatedBy: CharacterSet.decimalDigits.inverted).joined()) ?? 0
            let assets = (json["assets"] as? [[String: Any]]) ?? []
            let zip = assets.first { (Metadata.string($0["name"]) ?? "").hasSuffix(".zip") }
            lastChecked = Date()
            if build > currentBuild, let s = Metadata.string(zip?["browser_download_url"]), let url = URL(string: s) {
                available = Release(build: build, tag: tag, zipURL: url, notes: Metadata.string(json["body"]) ?? "")
                state = .idle
            } else {
                available = nil
                state = silent ? .idle : .upToDate
            }
        } catch {
            state = silent ? .idle : .failed(error.localizedDescription)
        }
    }

    func install() async {
        guard let release = available else { return }
        state = .downloading
        do {
            let (tmp, _) = try await URLSession.shared.download(from: release.zipURL)
            state = .installing
            let work = FileManager.default.temporaryDirectory.appendingPathComponent("qdl-update-\(release.build)")
            try? FileManager.default.removeItem(at: work)
            try FileManager.default.createDirectory(at: work, withIntermediateDirectories: true)
            let zip = work.appendingPathComponent("QDL-app.zip")
            try FileManager.default.moveItem(at: tmp, to: zip)

            let unzip = Process()
            unzip.executableURL = URL(fileURLWithPath: "/usr/bin/ditto")
            unzip.arguments = ["-x", "-k", zip.path, work.path]
            try unzip.run()
            unzip.waitUntilExit()

            guard let newApp = findApp(in: work) else {
                throw QobuzBridge.BridgeError(message: "The download didn't contain QDL.app.")
            }
            let dest = Bundle.main.bundlePath
            let pid = ProcessInfo.processInfo.processIdentifier
            let script = """
            #!/bin/bash
            while kill -0 \(pid) 2>/dev/null; do sleep 0.3; done
            rm -rf "\(dest).old"
            mv "\(dest)" "\(dest).old" && /usr/bin/ditto "\(newApp.path)" "\(dest)" && rm -rf "\(dest).old"
            /usr/bin/xattr -dr com.apple.quarantine "\(dest)" 2>/dev/null
            open "\(dest)"
            """
            let scriptURL = work.appendingPathComponent("install.sh")
            try script.write(to: scriptURL, atomically: true, encoding: .utf8)
            let runner = Process()
            runner.executableURL = URL(fileURLWithPath: "/bin/bash")
            runner.arguments = [scriptURL.path]
            try runner.run()
            NSApp.terminate(nil)
        } catch {
            state = .failed(error.localizedDescription)
        }
    }

    private func findApp(in dir: URL) -> URL? {
        guard let walker = FileManager.default.enumerator(at: dir, includingPropertiesForKeys: nil) else { return nil }
        for case let url as URL in walker where url.lastPathComponent == "QDL.app" {
            return url
        }
        return nil
    }
}

