struct Genre: Identifiable, Hashable {
    let id: String
    let name: String
}

struct FeaturedRow: Identifiable {
    let id: String
    let title: String
    let albums: [AlbumCard]
}

struct SearchResults {
    var albums: [AlbumCard] = []
    var tracks: [TrackCard] = []
    var artists: [ArtistCard] = []
    var playlists: [PlaylistCard] = []
    var isEmpty: Bool { albums.isEmpty && tracks.isEmpty && artists.isEmpty && playlists.isEmpty }
}

struct ArtistPage {
    let id: String
    let name: String
    let imageURL: URL?
    let albums: [AlbumCard]
    var url: String { "https://open.qobuz.com/artist/\(id)" }
}

struct MyQobuz {
    var albums: [AlbumCard] = []
    var tracks: [TrackCard] = []
    var artists: [ArtistCard] = []
    var playlists: [PlaylistCard] = []
}

enum LoadState: Equatable {
    case idle, loading, ready
    case failed(String)
}

enum ResultFilter: String, CaseIterable, Identifiable {
    case all = "All", albums = "Albums", tracks = "Tracks", artists = "Artists", playlists = "Playlists"
    var id: String { rawValue }
}

enum CatalogParse {
    static func album(_ d: [String: Any]) -> AlbumCard? {
        guard let id = Metadata.string(d["id"]) else { return nil }
        var title = Metadata.string(d["title"]) ?? "Untitled"
        if let v = Metadata.string(d["version"]) { title += " (\(v))" }
        return AlbumCard(
            id: id, title: title,
            artist: Metadata.name(d["artist"]) ?? "",
            year: Metadata.string(d["release_date_original"]).map { String($0.prefix(4)) },
            coverURL: Metadata.cover(d),
            bitDepth: Metadata.int(d["maximum_bit_depth"]),
            rate: Metadata.double(d["maximum_sampling_rate"]),
            releaseType: Metadata.string(d["release_type"]) ?? Metadata.string(d["product_type"]))
    }

    static func track(_ d: [String: Any]) -> TrackCard? {
        guard let id = Metadata.string(d["id"]) else { return nil }
        let album = d["album"] as? [String: Any]
        var title = Metadata.string(d["title"]) ?? "Untitled"
        if let v = Metadata.string(d["version"]), !title.lowercased().contains(v.lowercased()) { title += " (\(v))" }
        return TrackCard(
            id: id, title: title,
            artist: Metadata.name(d["performer"]) ?? Metadata.name(album?["artist"]) ?? "",
            album: Metadata.string(album?["title"]),
            albumID: Metadata.string(album?["id"]),
            coverURL: Metadata.cover(album),
            duration: Metadata.int(d["duration"]),
            bitDepth: Metadata.int(d["maximum_bit_depth"]),
            rate: Metadata.double(d["maximum_sampling_rate"]))
    }

    static func artist(_ d: [String: Any]) -> ArtistCard? {
        guard let id = Metadata.string(d["id"]) else { return nil }
        return ArtistCard(
            id: id, name: Metadata.string(d["name"]) ?? "Artist",
            imageURL: Metadata.image(d["image"]) ?? Metadata.string(d["picture"]).flatMap { URL(string: $0) },
            albums: Metadata.int(d["albums_count"]))
    }

    static func playlist(_ d: [String: Any]) -> PlaylistCard? {
        guard let id = Metadata.string(d["id"]) else { return nil }
        let images = (d["images300"] as? [String]) ?? (d["images"] as? [String]) ?? (d["images150"] as? [String]) ?? []
        return PlaylistCard(
            id: id, name: Metadata.string(d["name"]) ?? "Playlist",
            owner: Metadata.name(d["owner"]) ?? "",
            coverURL: images.first.flatMap { URL(string: $0) },
            tracks: Metadata.int(d["tracks_count"]))
    }

    static func albums(_ v: Any?) -> [AlbumCard] { Metadata.items(v).compactMap(album) }
    static func tracks(_ v: Any?) -> [TrackCard] { Metadata.items(v).compactMap(track) }
    static func artists(_ v: Any?) -> [ArtistCard] { Metadata.items(v).compactMap(artist) }
    static func playlists(_ v: Any?) -> [PlaylistCard] { Metadata.items(v).compactMap(playlist) }
}

// MARK: - Store / search / My Qobuz state

@MainActor
final class CatalogModel: ObservableObject {
    unowned let app: AppModel

    @Published var genres: [Genre] = []
    @Published var genreID: String?
    @Published var rows: [FeaturedRow] = []
    @Published var discoverState: LoadState = .idle

    @Published var query = ""
    @Published var results = SearchResults()
    @Published var searchState: LoadState = .idle
    @Published var filter: ResultFilter = .all

    @Published var artist: ArtistPage?
    @Published var artistState: LoadState = .idle

    @Published var mine = MyQobuz()
    @Published var mineState: LoadState = .idle

    private var searchToken = UUID()

    static let featuredKinds: [(String, String)] = [
        ("new-releases-full", "New releases"),
        ("press-awards", "Press awards"),
        ("editor-picks", "Editor's picks"),
        ("best-sellers", "Best sellers"),
    ]

    init(app: AppModel) { self.app = app }

    var isSearching: Bool { !query.trimmed.isEmpty }

    func loadDiscover(force: Bool = false) async {
        if discoverState == .loading { return }
        if discoverState == .ready && !force { return }
        discoverState = .loading
        do {
            if genres.isEmpty {
                let g = try await app.bridge.object("genres")
                genres = Metadata.items(g["genres"]).compactMap { d in
                    guard let id = Metadata.string(d["id"]), let name = Metadata.string(d["name"]) else { return nil }
                    return Genre(id: id, name: name)
                }
            }
            var built: [FeaturedRow] = []
            for (kind, title) in Self.featuredKinds {
                var args: [String: Any] = ["type": kind, "limit": 24]
                if let g = genreID { args["genre"] = g }
                if let r = try? await app.bridge.object("featured", args) {
                    let albums = CatalogParse.albums(r["albums"])
                    if !albums.isEmpty { built.append(FeaturedRow(id: kind, title: title, albums: albums)) }
                }
            }
            rows = built
            discoverState = built.isEmpty ? .failed("Qobuz didn't return any featured albums here. Try another genre, or search.") : .ready
        } catch {
            discoverState = .failed(error.localizedDescription)
        }
    }

    func pickGenre(_ id: String?) {
        genreID = id
        query = ""
        Task { await loadDiscover(force: true) }
    }

    func search(_ text: String) {
        let q = text.trimmed
        query = q
        app.go(.store)
        guard !q.isEmpty else { return }
        let token = UUID()
        searchToken = token
        searchState = .loading
        Task {
            do {
                let r = try await app.bridge.object("search", ["q": q, "limit": 30])
                guard searchToken == token else { return }
                results = SearchResults(albums: CatalogParse.albums(r["albums"]),
                                        tracks: CatalogParse.tracks(r["tracks"]),
                                        artists: CatalogParse.artists(r["artists"]),
                                        playlists: CatalogParse.playlists(r["playlists"]))
                searchState = .ready
            } catch {
                guard searchToken == token else { return }
                searchState = .failed(error.localizedDescription)
            }
        }
    }

    func clearSearch() {
        query = ""
        results = SearchResults()
        searchState = .idle
    }

    func openArtist(id: String, name: String? = nil) {
        app.go(.artist)
        if artist?.id == id && artistState == .ready { return }
        artist = ArtistPage(id: id, name: name ?? "Artist", imageURL: nil, albums: [])
        artistState = .loading
        Task {
            do {
                let r = try await app.bridge.object("meta", ["kind": "artist", "id": id])
                var albums = CatalogParse.albums(r["albums"])
                albums.sort { ($0.year ?? "") > ($1.year ?? "") }
                artist = ArtistPage(id: id, name: Metadata.string(r["name"]) ?? name ?? "Artist",
                                    imageURL: Metadata.image(r["image"]), albums: albums)
                artistState = .ready
            } catch {
                artistState = .failed(error.localizedDescription)
            }
        }
    }

    func loadMine(force: Bool = false) async {
        if mineState == .loading { return }
        if mineState == .ready && !force { return }
        mineState = .loading
        do {
            let fav = try await app.bridge.object("favorites")
            var m = MyQobuz(albums: CatalogParse.albums(fav["albums"]),
                            tracks: CatalogParse.tracks(fav["tracks"]),
                            artists: CatalogParse.artists(fav["artists"]))
            if let pl = try? await app.bridge.object("playlists") {
                m.playlists = CatalogParse.playlists(pl["playlists"])
            }
            mine = m
            mineState = .ready
        } catch {
            mineState = .failed(error.localizedDescription)
        }
    }
}

