import SwiftUI
import AppKit

// MARK: - Store

struct StoreView: View {
    @EnvironmentObject var catalog: CatalogModel

    var body: some View {
        if catalog.isSearching {
            SearchResultsView()
        } else {
            DiscoverView()
        }
    }
}

/// Shown instead of store content when the engine or account isn't set up yet.
struct SetupNeeded: View {
    @EnvironmentObject var model: AppModel
    @Environment(\.qdl) private var t

    var body: some View {
        VStack(spacing: 14) {
            Image(systemName: model.engine.isReady ? "person.crop.circle.badge.exclamationmark" : "shippingbox")
                .font(.system(size: 44, weight: .light))
                .foregroundStyle(t.accent)
            Text(model.engine.isReady ? "Add your Qobuz account" : "Install the download engine")
                .font(.system(size: 22, weight: .bold))
            Text(model.engine.isReady
                 ? "The store, search and My Qobuz use your own Qobuz login."
                 : "QDL needs streamrip and ffmpeg to talk to Qobuz. Use Install Engine in the sidebar.")
                .foregroundStyle(t.sub)
                .multilineTextAlignment(.center)
                .frame(maxWidth: 420)
            if model.engine.isReady {
                AccentButton(title: "Add Account", icon: "person.crop.circle") { model.showAccount = true }
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }
}

struct FailedNote: View {
    @Environment(\.qdl) private var t
    let message: String
    let retry: () -> Void

    var body: some View {
        HStack(spacing: 12) {
            Image(systemName: "exclamationmark.triangle").foregroundStyle(t.warn)
            Text(message).foregroundStyle(t.sub).fixedSize(horizontal: false, vertical: true)
            Spacer()
            Button("Try Again", action: retry)
        }
        .padding(14)
        .glass(14)
    }
}

struct DiscoverView: View {
    @EnvironmentObject var model: AppModel
    @EnvironmentObject var catalog: CatalogModel
    @Environment(\.qdl) private var t

    private var eyebrow: String {
        guard let g = catalog.genreID, let name = catalog.genres.first(where: { $0.id == g })?.name else { return "DISCOVER" }
        return name.uppercased()
    }

    var body: some View {
        if !model.engine.isReady || !model.hasCredentials {
            SetupNeeded()
        } else {
            ScrollView {
                VStack(alignment: .leading, spacing: 28) {
                    HStack(alignment: .bottom) {
                        VStack(alignment: .leading, spacing: 4) {
                            Text(eyebrow).font(.system(size: 12, weight: .semibold)).foregroundStyle(t.sub)
                            Text("Store").font(.system(size: 36, weight: .bold))
                        }
                        Spacer()
                        Button {
                            Task { await catalog.loadDiscover(force: true) }
                        } label: {
                            Image(systemName: "arrow.clockwise").frame(width: 32, height: 32).contentShape(Circle())
                        }
                        .buttonStyle(.plain)
                        .glass(16)
                        .help("Refresh")
                        .accessibilityLabel("Refresh")
                    }

                    if !catalog.genres.isEmpty {
                        ScrollView(.horizontal, showsIndicators: false) {
                            HStack(spacing: 6) {
                                GenreChip(title: "All genres", on: catalog.genreID == nil) { catalog.pickGenre(nil) }
                                ForEach(catalog.genres) { g in
                                    GenreChip(title: g.name, on: catalog.genreID == g.id) { catalog.pickGenre(g.id) }
                                }
                            }
                            .padding(.vertical, 2)
                        }
                    }

                    if catalog.discoverState == .loading && catalog.rows.isEmpty {
                        HStack { Spacer(); ProgressView().controlSize(.large); Spacer() }.padding(.top, 80)
                    } else if case .failed(let m) = catalog.discoverState {
                        FailedNote(message: m) { Task { await catalog.loadDiscover(force: true) } }
                    }

                    ForEach(catalog.rows) { row in
                        VStack(alignment: .leading, spacing: 12) {
                            Text(row.title).font(.system(size: 20, weight: .bold))
                            ScrollView(.horizontal, showsIndicators: false) {
                                LazyHStack(alignment: .top, spacing: 16) {
                                    ForEach(row.albums) { a in
                                        AlbumCardView(album: a)
                                    }
                                }
                                .padding(.bottom, 8)
                            }
                        }
                    }
                }
                .padding(.horizontal, 24)
                .padding(.vertical, 18)
            }
            .task { await catalog.loadDiscover() }
        }
    }
}

struct GenreChip: View {
    @Environment(\.qdl) private var t
    let title: String
    let on: Bool
    let action: () -> Void

    var body: some View {
        Button(action: action) {
            Text(title)
                .font(.system(size: 12.5, weight: .semibold))
                .padding(.horizontal, 14)
                .frame(height: 30)
                .foregroundStyle(on ? t.buttonText : t.text)
                .background(Capsule().fill(on ? t.button : t.control))
                .overlay(Capsule().strokeBorder(t.border))
                .contentShape(Capsule())
        }
        .buttonStyle(.plain)
        .accessibilityAddTraits(on ? .isSelected : [])
    }
}

struct SearchResultsView: View {
    @EnvironmentObject var model: AppModel
    @EnvironmentObject var catalog: CatalogModel
    @Environment(\.qdl) private var t

    private func shows(_ f: ResultFilter) -> Bool { catalog.filter == .all || catalog.filter == f }

    var body: some View {
        let r = catalog.results
        ScrollView {
            VStack(alignment: .leading, spacing: 26) {
                HStack(alignment: .firstTextBaseline) {
                    Text("Results for “\(catalog.query)”").font(.system(size: 28, weight: .bold)).lineLimit(1)
                    Spacer()
                    Button("Clear Search") {
                        catalog.clearSearch()
                        model.linkField = ""
                    }
                }
                HStack(spacing: 6) {
                    ForEach(ResultFilter.allCases) { f in
                        GenreChip(title: f.rawValue, on: catalog.filter == f) { catalog.filter = f }
                    }
                }

                if catalog.searchState == .loading {
                    HStack { Spacer(); ProgressView().controlSize(.large); Spacer() }.padding(.top, 60)
                } else if case .failed(let m) = catalog.searchState {
                    FailedNote(message: m) { catalog.search(catalog.query) }
                } else if catalog.searchState == .ready && r.isEmpty {
                    Text("Nothing found on Qobuz for that search.").foregroundStyle(t.sub).padding(.top, 40)
                } else {
                    if catalog.filter == .all, let top = r.artists.first {
                        HStack(alignment: .top, spacing: 16) {
                            TopArtistCard(artist: top)
                                .frame(width: 320)
                            VStack(alignment: .leading, spacing: 2) {
                                Text("Tracks").font(.system(size: 18, weight: .bold)).padding(.bottom, 6)
                                ForEach(r.tracks.prefix(5)) { tr in TrackResultRow(track: tr) }
                            }
                        }
                    } else if shows(.tracks) && !r.tracks.isEmpty {
                        VStack(alignment: .leading, spacing: 2) {
                            Text("Tracks").font(.system(size: 18, weight: .bold)).padding(.bottom, 6)
                            ForEach(catalog.filter == .tracks ? Array(r.tracks) : Array(r.tracks.prefix(6))) { tr in
                                TrackResultRow(track: tr)
                            }
                        }
                    }

                    if shows(.albums) && !r.albums.isEmpty {
                        VStack(alignment: .leading, spacing: 12) {
                            Text("Albums").font(.system(size: 18, weight: .bold))
                            LazyVGrid(columns: [GridItem(.adaptive(minimum: 150, maximum: 190), spacing: 18)],
                                      alignment: .leading, spacing: 20) {
                                ForEach(r.albums) { a in AlbumCardView(album: a, size: 150) }
                            }
                        }
                    }

                    if shows(.artists) && !r.artists.isEmpty {
                        VStack(alignment: .leading, spacing: 12) {
                            Text("Artists").font(.system(size: 18, weight: .bold))
                            ScrollView(.horizontal, showsIndicators: false) {
                                HStack(alignment: .top, spacing: 20) {
                                    ForEach(r.artists) { a in ArtistCircle(artist: a) }
                                }
                                .padding(.bottom, 6)
                            }
                        }
                    }

                    if shows(.playlists) && !r.playlists.isEmpty {
                        VStack(alignment: .leading, spacing: 12) {
                            Text("Playlists").font(.system(size: 18, weight: .bold))
                            LazyVGrid(columns: [GridItem(.adaptive(minimum: 150, maximum: 190), spacing: 18)],
                                      alignment: .leading, spacing: 20) {
                                ForEach(r.playlists) { p in PlaylistCardView(playlist: p) }
                            }
                        }
                    }
                }
            }
            .padding(.horizontal, 24)
            .padding(.vertical, 18)
        }
    }
}

// MARK: - Cards and rows

struct AlbumCardView: View {
    @EnvironmentObject var model: AppModel
    @EnvironmentObject var catalog: CatalogModel
    @Environment(\.qdl) private var t
    let album: AlbumCard
    var size: CGFloat = 168

    var body: some View {
        Button {
            model.openLink(album.url)
        } label: {
            VStack(alignment: .leading, spacing: 6) {
                CoverView(url: album.coverURL, size: size, radius: 12)
                    .shadow(color: .black.opacity(0.35), radius: 14, y: 8)
                Text(album.title).font(.system(size: 13.5, weight: .semibold)).lineLimit(1)
                Text(album.artist + (album.year.map { " · \($0)" } ?? ""))
                    .font(.system(size: 12))
                    .foregroundStyle(t.sub)
                    .lineLimit(1)
                if !album.badge.isEmpty {
                    Text(album.badge)
                        .font(.system(size: 10.5, weight: .semibold))
                        .padding(.horizontal, 7)
                        .padding(.vertical, 2)
                        .foregroundStyle(album.hiRes ? t.badgeText : t.sub)
                        .background(Capsule().fill(album.hiRes ? t.badgeFill : t.control))
                }
            }
            .frame(width: size, alignment: .leading)
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .help("\(album.title) — \(album.artist)")
        .contextMenu {
            Button("Open Album") { model.openLink(album.url) }
            Button("Download Whole Album") {
                model.downloadWhole(title: album.title, artist: album.artist, coverURL: album.coverURL,
                                    link: album.url, kind: "album")
            }
            Divider()
            Button("Copy Link") {
                NSPasteboard.general.clearContents()
                NSPasteboard.general.setString(album.url, forType: .string)
            }
        }
    }
}

struct PlaylistCardView: View {
    @EnvironmentObject var model: AppModel
    @Environment(\.qdl) private var t
    let playlist: PlaylistCard
    var size: CGFloat = 150

    var body: some View {
        Button {
            model.openLink(playlist.url)
        } label: {
            VStack(alignment: .leading, spacing: 6) {
                CoverView(url: playlist.coverURL, size: size, radius: 12)
                    .shadow(color: .black.opacity(0.35), radius: 14, y: 8)
                Text(playlist.name).font(.system(size: 13.5, weight: .semibold)).lineLimit(1)
                Text(playlist.tracks > 0 ? "\(playlist.tracks) tracks" + (playlist.owner.isEmpty ? "" : " · \(playlist.owner)") : playlist.owner)
                    .font(.system(size: 12))
                    .foregroundStyle(t.sub)
                    .lineLimit(1)
            }
            .frame(width: size, alignment: .leading)
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
    }
}

struct ArtistCircle: View {
    @EnvironmentObject var catalog: CatalogModel
    @Environment(\.qdl) private var t
    let artist: ArtistCard
    var size: CGFloat = 104

    var body: some View {
        Button {
            catalog.openArtist(id: artist.id, name: artist.name)
        } label: {
            VStack(spacing: 8) {
                ArtistImage(url: artist.imageURL, name: artist.name, size: size)
                Text(artist.name)
                    .font(.system(size: 13, weight: .semibold))
                    .multilineTextAlignment(.center)
                    .lineLimit(2)
                    .frame(width: size + 10)
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
    }
}

struct ArtistImage: View {
    @Environment(\.qdl) private var t
    let url: URL?
    let name: String
    let size: CGFloat

    var body: some View {
        ZStack {
            Circle().fill(LinearGradient(colors: [t.accent.opacity(0.8), t.accent.opacity(0.3)],
                                         startPoint: .topLeading, endPoint: .bottomTrailing))
            Text(String(name.prefix(1)).uppercased())
                .font(.system(size: size * 0.4, weight: .bold))
                .foregroundStyle(Color.white.opacity(0.9))
            if let url {
                AsyncImage(url: url) { img in
                    img.resizable().aspectRatio(contentMode: .fill)
                } placeholder: {
                    Color.clear
                }
            }
        }
        .frame(width: size, height: size)
        .clipShape(Circle())
        .shadow(color: .black.opacity(0.35), radius: 12, y: 6)
        .accessibilityHidden(true)
    }
}

struct TopArtistCard: View {
    @EnvironmentObject var catalog: CatalogModel
    @Environment(\.qdl) private var t
    let artist: ArtistCard

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            Text("TOP RESULT").font(.system(size: 11.5, weight: .semibold)).foregroundStyle(t.sub)
            ArtistImage(url: artist.imageURL, name: artist.name, size: 96)
            VStack(alignment: .leading, spacing: 4) {
                Text(artist.name).font(.system(size: 24, weight: .bold)).lineLimit(2)
                Text(artist.albums > 0 ? "Artist · \(artist.albums) releases" : "Artist")
                    .font(.system(size: 13))
                    .foregroundStyle(t.sub)
            }
            AccentButton(title: "Open Artist", icon: "person.fill") {
                catalog.openArtist(id: artist.id, name: artist.name)
            }
        }
        .padding(20)
        .frame(maxWidth: .infinity, alignment: .leading)
        .glass(20)
    }
}

struct PlayButton: View {
    @EnvironmentObject var player: AudioPlayer
    @Environment(\.qdl) private var t
    let id: String
    let title: String
    let artist: String
    let coverURL: URL?
    let duration: Int
    var size: CGFloat = 26

    var body: some View {
        let current = player.isCurrent(id)
        Button {
            player.play(id: id, title: title, artist: artist, coverURL: coverURL, duration: duration)
        } label: {
            ZStack {
                Circle().fill(current ? t.button : t.control)
                if player.loadingID == id {
                    ProgressView().controlSize(.mini)
                } else {
                    Image(systemName: current && player.isPlaying ? "pause.fill" : "play.fill")
                        .font(.system(size: size * 0.38, weight: .bold))
                        .foregroundStyle(current ? t.buttonText : t.text)
                        .offset(x: current && player.isPlaying ? 0 : 1)
                }
            }
            .frame(width: size, height: size)
            .contentShape(Circle())
        }
        .buttonStyle(.plain)
        .help(current && player.isPlaying ? "Pause preview" : "Play preview")
        .accessibilityLabel(current && player.isPlaying ? "Pause \(title)" : "Play \(title)")
    }
}

struct TrackResultRow: View {
    @EnvironmentObject var model: AppModel
    @Environment(\.qdl) private var t
    let track: TrackCard

    var body: some View {
        HStack(spacing: 12) {
            ZStack {
                CoverView(url: track.coverURL, size: 40, radius: 6)
                PlayButton(id: track.id, title: track.title, artist: track.artist, coverURL: track.coverURL,
                           duration: track.duration, size: 26)
            }
            VStack(alignment: .leading, spacing: 1) {
                Text(track.title).font(.system(size: 14)).lineLimit(1)
                Text(track.artist + (track.album.map { " · \($0)" } ?? ""))
                    .font(.system(size: 12))
                    .foregroundStyle(t.sub)
                    .lineLimit(1)
            }
            Spacer(minLength: 8)
            Text(track.qualityText).font(.system(size: 12)).foregroundStyle(t.sub).frame(width: 64, alignment: .trailing)
            Text(track.durationText).font(.system(size: 13).monospacedDigit()).foregroundStyle(t.sub).frame(width: 48, alignment: .trailing)
            Button {
                model.downloadTrack(track)
            } label: {
                Image(systemName: "arrow.down.circle").font(.system(size: 18))
            }
            .buttonStyle(.plain)
            .foregroundStyle(t.accent)
            .help("Download this track")
            .accessibilityLabel("Download \(track.title)")
        }
        .padding(.horizontal, 10)
        .frame(minHeight: 52)
