import SwiftUI
import AppKit

// MARK: - Artist

struct ArtistView: View {
    @EnvironmentObject var model: AppModel
    @EnvironmentObject var catalog: CatalogModel
    @Environment(\.qdl) private var t
    @State private var showDiscography = false

    struct AlbumGroup: Identifiable {
        let id: String
        let albums: [AlbumCard]
    }

    private func group(_ albums: [AlbumCard]) -> [AlbumGroup] {
        var main: [AlbumCard] = []
        var small: [AlbumCard] = []
        var other: [AlbumCard] = []
        for a in albums {
            switch (a.releaseType ?? "album").lowercased() {
            case "album": main.append(a)
            case "single", "epmini", "ep", "epsingle": small.append(a)
            default: other.append(a)
            }
        }
        return [AlbumGroup(id: "Albums", albums: main),
                AlbumGroup(id: "Singles & EPs", albums: small),
                AlbumGroup(id: "Live, compilations & more", albums: other)].filter { !$0.albums.isEmpty }
    }

    var body: some View {
        if let a = catalog.artist {
            ScrollView {
                VStack(alignment: .leading, spacing: 26) {
                    HStack(alignment: .bottom, spacing: 24) {
                        ArtistImage(url: a.imageURL, name: a.name, size: 180)
                        VStack(alignment: .leading, spacing: 10) {
                            Text("ARTIST").font(.system(size: 11.5, weight: .semibold)).foregroundStyle(t.sub)
                            Text(a.name).font(.system(size: 40, weight: .bold)).lineLimit(2)
                            if !a.albums.isEmpty {
                                Text("\(a.albums.count) releases on Qobuz").font(.system(size: 13)).foregroundStyle(t.sub)
                            }
                            AccentButton(title: "Download Discography…", icon: "square.stack.3d.down.right") {
                                showDiscography = true
                            }
                            .padding(.top, 4)
                        }
                        Spacer(minLength: 0)
                    }

                    if catalog.artistState == .loading {
                        HStack { Spacer(); ProgressView().controlSize(.large); Spacer() }.padding(.top, 40)
                    } else if case .failed(let m) = catalog.artistState {
                        FailedNote(message: m) { catalog.openArtist(id: a.id, name: a.name) }
                    }

                    ForEach(group(a.albums)) { section in
                        VStack(alignment: .leading, spacing: 12) {
                            Text(section.id).font(.system(size: 18, weight: .bold))
                            LazyVGrid(columns: [GridItem(.adaptive(minimum: 150, maximum: 190), spacing: 18)],
                                      alignment: .leading, spacing: 20) {
                                ForEach(section.albums) { album in AlbumCardView(album: album, size: 150) }
                            }
                        }
                    }
                }
                .padding(.horizontal, 24)
                .padding(.vertical, 18)
            }
            .sheet(isPresented: $showDiscography) {
                DiscographySheet(artist: a)
                    .environmentObject(model)
                    .environment(\.qdl, t)
            }
        } else {
            Text("Search for an artist in the Store.").foregroundStyle(t.sub)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
    }
}

