// MARK: - Credits, lyrics, booklet

enum Lyrics {
    static func fetch(artist: String, title: String, album: String?, duration: Int) async -> String? {
        let cleanTitle = title.replacingOccurrences(of: #"\s*[\(\[].*?[\)\]]"#, with: "", options: .regularExpression).trimmed
        func get(_ path: String, _ items: [URLQueryItem]) async -> Any? {
            var c = URLComponents(string: "https://lrclib.net/api/" + path)!
            c.queryItems = items
            guard let url = c.url else { return nil }
            var req = URLRequest(url: url)
            req.setValue("QDL (https://github.com/hisham-alfar/QDL)", forHTTPHeaderField: "User-Agent")
            guard let result = try? await URLSession.shared.data(for: req),
                  (result.1 as? HTTPURLResponse)?.statusCode == 200 else { return nil }
            return try? JSONSerialization.jsonObject(with: result.0)
        }
        var items = [URLQueryItem(name: "artist_name", value: artist), URLQueryItem(name: "track_name", value: cleanTitle)]
        if let album { items.append(URLQueryItem(name: "album_name", value: album)) }
        if duration > 0 { items.append(URLQueryItem(name: "duration", value: String(duration))) }
        if let d = await get("get", items) as? [String: Any], let text = Metadata.string(d["plainLyrics"]) {
            return text
        }
        let search = [URLQueryItem(name: "artist_name", value: artist), URLQueryItem(name: "track_name", value: cleanTitle)]
        if let list = await get("search", search) as? [[String: Any]] {
            for d in list { if let text = Metadata.string(d["plainLyrics"]) { return text } }
        }
        return nil
    }
}

