struct TrackInfoSheet: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.qdl) private var t
    let track: PreviewTrack
    let albumArtist: String
    let albumTitle: String?
    @State private var tab: InfoTab = .credits
    @State private var lyrics: String?
    @State private var lyricsLoaded = false

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            HStack(alignment: .top) {
                VStack(alignment: .leading, spacing: 2) {
                    Text(track.title).font(.title2.weight(.bold)).lineLimit(2)
                    Text(track.artist ?? albumArtist).foregroundStyle(.secondary)
                }
                Spacer()
                Button("Done") { dismiss() }.keyboardShortcut(.defaultAction)
            }
            Picker("Show", selection: $tab) {
                ForEach(InfoTab.allCases) { Text($0.rawValue).tag($0) }
            }
            .pickerStyle(.segmented)
            .labelsHidden()

            ScrollView {
                VStack(alignment: .leading, spacing: 10) {
                    if tab == .credits {
                        let rows = Metadata.credits(track.performers)
                        if rows.isEmpty {
                            Text("Qobuz has no credits for this track.").foregroundStyle(.secondary)
                        }
                        ForEach(Array(rows.enumerated()), id: \.offset) { _, row in
                            VStack(alignment: .leading, spacing: 1) {
                                Text(row.0).font(.body.weight(.semibold))
                                if !row.1.isEmpty { Text(row.1).font(.callout).foregroundStyle(.secondary) }
                            }
                        }
                    } else if !lyricsLoaded {
                        HStack { ProgressView().controlSize(.small); Text("Looking up lyrics…").foregroundStyle(.secondary) }
                    } else if let lyrics {
                        Text(lyrics).font(.body).textSelection(.enabled).lineSpacing(3)
                        Text("Lyrics from LRCLIB").font(.caption).foregroundStyle(.secondary).padding(.top, 8)
                    } else {
                        Text("No lyrics found for this track.").foregroundStyle(.secondary)
                    }
                }
                .frame(maxWidth: .infinity, alignment: .leading)
            }
        }
        .padding(24)
        .frame(width: 520, height: 560)
        .task(id: tab) {
            guard tab == .lyrics, !lyricsLoaded else { return }
            lyrics = await Lyrics.fetch(artist: track.artist ?? albumArtist, title: track.title,
                                        album: albumTitle ?? track.album, duration: track.duration)
            lyricsLoaded = true
        }
    }
}

enum BookletOpener {
    static func open(_ booklet: Booklet) async {
        let dest = FileManager.default.temporaryDirectory
            .appendingPathComponent(booklet.name.replacingOccurrences(of: "/", with: "-") + ".pdf")
        if let result = try? await URLSession.shared.download(from: booklet.url) {
            try? FileManager.default.removeItem(at: dest)
            if (try? FileManager.default.moveItem(at: result.0, to: dest)) != nil {
                NSWorkspace.shared.open(dest)
                return
            }
        }
        NSWorkspace.shared.open(booklet.url)
    }
}

