import Foundation
import Accelerate

/// Estimates tempo (BPM) and musical key from decoded mono audio.
enum Analyzer {
    struct Result {
        let bpm: Double?
        let key: String?
        let camelot: String?
    }

    static let names = ["C", "C♯", "D", "E♭", "E", "F", "F♯", "G", "A♭", "A", "B♭", "B"]
    private static let camelotMajor = [8, 3, 10, 5, 12, 7, 2, 9, 4, 11, 6, 1]
    private static let camelotMinor = [5, 12, 7, 2, 9, 4, 11, 6, 1, 8, 3, 10]
    private static let majorProfile: [Double] = [6.35, 2.23, 3.48, 2.33, 4.38, 4.09, 2.52, 5.19, 2.39, 3.66, 2.29, 2.88]
    private static let minorProfile: [Double] = [6.33, 2.68, 3.52, 5.38, 2.60, 3.53, 2.54, 4.75, 3.98, 2.69, 3.34, 3.17]

    static func analyze(samples x: [Float], rate: Double) -> Result {
        let n = 2048
        let half = n / 2
        let hop = 512
        let log2n = vDSP_Length(11)
        guard x.count > n * 8, let setup = vDSP_create_fftsetup(log2n, FFTRadix(kFFTRadix2)) else {
            return Result(bpm: nil, key: nil, camelot: nil)
        }
        defer { vDSP_destroy_fftsetup(setup) }

        var window = [Float](repeating: 0, count: n)
        vDSP_hann_window(&window, vDSP_Length(n), Int32(vDSP_HANN_NORM))

        var pcOfBin = [Int](repeating: -1, count: half)
        for k in 1..<half {
            let f = Double(k) * rate / Double(n)
            if f >= 55 && f <= 2000 {
                let p = 12 * log2(f / 440) + 69
                pcOfBin[k] = ((Int(p.rounded()) % 12) + 12) % 12
            }
        }

        var frame = [Float](repeating: 0, count: n)
        var real = [Float](repeating: 0, count: half)
        var imag = [Float](repeating: 0, count: half)
        var mags = [Float](repeating: 0, count: half)
        var prev = [Float](repeating: 0, count: half)
        var flux: [Float] = []
        var chroma = [Double](repeating: 0, count: 12)

        var start = 0
        while start + n <= x.count {
            x.withUnsafeBufferPointer { buf in
                vDSP_vmul(buf.baseAddress! + start, 1, window, 1, &frame, 1, vDSP_Length(n))
            }
            real.withUnsafeMutableBufferPointer { rp in
                imag.withUnsafeMutableBufferPointer { ip in
                    var split = DSPSplitComplex(realp: rp.baseAddress!, imagp: ip.baseAddress!)
                    frame.withUnsafeBufferPointer { fp in
                        fp.baseAddress!.withMemoryRebound(to: DSPComplex.self, capacity: half) { cp in
                            vDSP_ctoz(cp, 2, &split, 1, vDSP_Length(half))
                        }
                    }
                    vDSP_fft_zrip(setup, &split, 1, log2n, FFTDirection(FFT_FORWARD))
                    vDSP_zvabs(&split, 1, &mags, 1, vDSP_Length(half))
                }
            }
            var f: Float = 0
            for k in 1..<half {
                let m = log1pf(mags[k])
                let d = m - prev[k]
                if d > 0 { f += d }
                prev[k] = m
                let pc = pcOfBin[k]
                if pc >= 0 { chroma[pc] += Double(mags[k]) }
            }
            flux.append(f)
            start += hop
        }

        return Result(bpm: tempo(flux: flux, fps: rate / Double(hop)), key: keyName(chroma), camelot: camelot(chroma))
    }

    private static func tempo(flux: [Float], fps: Double) -> Double? {
        guard flux.count > 200 else { return nil }
        let mean = flux.reduce(0, +) / Float(flux.count)
        let env = flux.map { max(0, $0 - mean) }
        let minLag = max(2, Int(fps * 60 / 185))
        let maxLag = Int(fps * 60 / 68)
        guard maxLag < env.count / 2 else { return nil }
        var scores = [Double](repeating: 0, count: maxLag + 2)
        for lag in minLag...maxLag {
            var s: Float = 0
            for i in 0..<(env.count - lag) { s += env[i] * env[i + lag] }
            let bpm = 60 * fps / Double(lag)
            let w = exp(-0.5 * pow(log2(bpm / 120) / 1.0, 2))
            scores[lag] = Double(s) * w
        }
        var best = minLag
        for lag in minLag...maxLag where scores[lag] > scores[best] { best = lag }
        var lag = Double(best)
        if best > minLag && best < maxLag {
            let a = scores[best - 1], b = scores[best], c = scores[best + 1]
            let denom = a - 2 * b + c
            if denom != 0 { lag += 0.5 * (a - c) / denom }
        }
        var bpm = 60 * fps / lag
        while bpm < 70 { bpm *= 2 }
        while bpm > 180 { bpm /= 2 }
        return (bpm * 2).rounded() / 2
    }

    private static func bestKey(_ chroma: [Double]) -> (pc: Int, minor: Bool)? {
        let total = chroma.reduce(0, +)
        guard total > 0 else { return nil }
        func corr(_ a: [Double], _ b: [Double]) -> Double {
            let ma = a.reduce(0, +) / 12, mb = b.reduce(0, +) / 12
            var num = 0.0, da = 0.0, db = 0.0
            for i in 0..<12 {
                num += (a[i] - ma) * (b[i] - mb)
                da += (a[i] - ma) * (a[i] - ma)
                db += (b[i] - mb) * (b[i] - mb)
            }
            return da > 0 && db > 0 ? num / (da * db).squareRoot() : 0
        }
        var best: (Int, Bool, Double) = (0, false, -2)
        for r in 0..<12 {
            let maj = (0..<12).map { majorProfile[($0 - r + 12) % 12] }
            let min = (0..<12).map { minorProfile[($0 - r + 12) % 12] }
            let cm = corr(chroma, maj)
            let cn = corr(chroma, min)
            if cm > best.2 { best = (r, false, cm) }
            if cn > best.2 { best = (r, true, cn) }
        }
        return (best.0, best.1)
    }

    private static func keyName(_ chroma: [Double]) -> String? {
        guard let k = bestKey(chroma) else { return nil }
        return names[k.pc] + (k.minor ? " minor" : " major")
    }

    private static func camelot(_ chroma: [Double]) -> String? {
        guard let k = bestKey(chroma) else { return nil }
        return k.minor ? "\(camelotMinor[k.pc])A" : "\(camelotMajor[k.pc])B"
    }

    /// Reads raw little-endian Float32 samples written by ffmpeg.
    static func loadRaw(_ url: URL) -> [Float] {
        guard let data = try? Data(contentsOf: url), data.count >= 4 else { return [] }
        let count = data.count / MemoryLayout<Float>.size
        return data.withUnsafeBytes { raw in
            Array(raw.bindMemory(to: Float.self).prefix(count))
        }
    }
}

