import SwiftUI
import AppKit

// MARK: - Library records

struct LibraryTrack: Codable, Identifiable, Hashable {
    var id: String { path }
    let path: String
    var title: String
    var number: Int
    var bpm: Double?
    var key: String?
    var camelot: String?
    var analyzed = false

    var url: URL { URL(fileURLWithPath: path) }
}

struct LibraryAlbum: Codable, Identifiable, Hashable {
    var id: String { folder }
    var title: String
    var artist: String
    var albumID: String?
    var folder: String
    var bitDepth: Int
    var rate: Double
    var format: String
    var added: Date
    var bestBitDepth: Int = 0
    var bestRate: Double = 0
    var tracks: [LibraryTrack]

    var folderURL: URL { URL(fileURLWithPath: folder, isDirectory: true) }
    var qualityText: String {
        bitDepth > 0 ? "\(Preview.qualityText(bitDepth: bitDepth, rate: rate)) \(format)" : format
    }
    var canUpgrade: Bool {
        bestBitDepth > bitDepth || (bestBitDepth == bitDepth && bestRate > rate + 0.5)
    }
    var coverURL: URL? {
        for name in ["cover.jpg", "cover.png", "folder.jpg"] {
            let u = folderURL.appendingPathComponent(name)
            if FileManager.default.fileExists(atPath: u.path) { return u }
        }
        return nil
    }
}

enum AppleMusicMode: String, CaseIterable, Identifiable {
    case alac, original
    var id: String { rawValue }
    var label: String { self == .alac ? "Apple Lossless (ALAC) copy" : "Original files when Music supports them" }
}

// MARK: - Library store

@MainActor
final class LibraryStore: ObservableObject {
    unowned let app: AppModel

    @Published var albums: [LibraryAlbum] = []
    @Published var scanning = false
    @Published var analyzing: Set<String> = []
    @Published var status: String?

    private let runner = ProcessRunner()
    private var indexURL: URL { Paths.support.appendingPathComponent("library.json") }
    static let audioExts: Set<String> = ["flac", "m4a", "mp3", "wav", "aif", "aiff", "opus", "ogg"]

    init(app: AppModel) {
        self.app = app
        load()
    }

    // MARK: Persistence

    private func load() {
        guard let data = try? Data(contentsOf: indexURL) else { return }
        let dec = JSONDecoder()
        dec.dateDecodingStrategy = .iso8601
        albums = (try? dec.decode([LibraryAlbum].self, from: data)) ?? []
        prune()
    }

    private func save() {
        let enc = JSONEncoder()
        enc.dateEncodingStrategy = .iso8601
        enc.outputFormatting = [.prettyPrinted]
        if let data = try? enc.encode(albums) { try? data.write(to: indexURL, options: .atomic) }
    }

    /// Drops albums whose folder was deleted.
    func prune() {
        let before = albums.count
        albums.removeAll { !FileManager.default.fileExists(atPath: $0.folder) }
        for i in albums.indices {
            albums[i].tracks.removeAll { !FileManager.default.fileExists(atPath: $0.path) }
        }
        if albums.count != before { save() }
    }

    // MARK: Lookups

    func match(for p: Preview) -> LibraryAlbum? {
        if let a = albums.first(where: { $0.albumID == p.id && p.kind == "album" }) { return a }
        let t = p.title.lowercased(), ar = p.artist.lowercased()
        return albums.first { $0.title.lowercased() == t && $0.artist.lowercased() == ar }
    }

    // MARK: Recording downloads

    /// Called when a download job finishes: groups its new files by folder and records them.
    func record(job: DownloadJob, files: [URL]) async -> [LibraryAlbum] {
        let audio = files.filter { Self.audioExts.contains($0.pathExtension.lowercased()) &&
                                   FileManager.default.fileExists(atPath: $0.path) }
        guard !audio.isEmpty else { return [] }
        let groups = Dictionary(grouping: audio) { $0.deletingLastPathComponent().path }
        var touched: [LibraryAlbum] = []
        for (folder, urls) in groups {
            let q = await probe(urls[0])
            let tracks = urls.sorted { $0.lastPathComponent < $1.lastPathComponent }.map { u in
                LibraryTrack(path: u.path, title: Self.titleFromFile(u), number: Self.numberFromFile(u))
            }
            if let i = albums.firstIndex(where: { $0.folder == folder }) {
                var a = albums[i]
                for t in tracks where !a.tracks.contains(where: { $0.path == t.path }) { a.tracks.append(t) }
                a.tracks.sort { $0.number < $1.number }
                a.bitDepth = q.depth; a.rate = q.rate; a.format = q.format
                if job.bestBitDepth > 0 { a.bestBitDepth = job.bestBitDepth; a.bestRate = job.bestRate }
                if a.albumID == nil { a.albumID = job.albumID }
                albums[i] = a
                touched.append(a)
            } else {
                let isAlbum = job.kind == "album" || job.kind == "track"
                let (guessTitle, guessArtist) = Self.guess(folder: URL(fileURLWithPath: folder).lastPathComponent)
                let a = LibraryAlbum(
                    title: isAlbum ? (job.kind == "track" ? (guessTitle ?? job.title) : job.title) : (guessTitle ?? job.title),
                    artist: isAlbum ? job.artist : (guessArtist ?? job.artist),
                    albumID: job.kind == "album" ? job.albumID : nil,
                    folder: folder, bitDepth: q.depth, rate: q.rate, format: q.format, added: Date(),
                    bestBitDepth: job.bestBitDepth, bestRate: job.bestRate,
                    tracks: tracks.sorted { $0.number < $1.number })
                albums.insert(a, at: 0)
                touched.append(a)
            }
        }
        save()
        return touched
    }

    /// Adds folders already in the download folder that QDL doesn't know about yet.
    func scan() async {
        guard !scanning else { return }
        scanning = true
        status = "Scanning \(app.folderDisplay)…"
        var byFolder: [String: [URL]] = [:]
        if let walker = FileManager.default.enumerator(at: app.folder, includingPropertiesForKeys: nil,
                                                       options: [.skipsHiddenFiles]) {
            for case let url as URL in walker where Self.audioExts.contains(url.pathExtension.lowercased()) {
                byFolder[url.deletingLastPathComponent().path, default: []].append(url)
            }
        }
        var added = 0
        for (folder, urls) in byFolder where !albums.contains(where: { $0.folder == folder }) {
            let q = await probe(urls[0])
            let (t, a) = Self.guess(folder: URL(fileURLWithPath: folder).lastPathComponent)
            let tracks = urls.sorted { $0.lastPathComponent < $1.lastPathComponent }.map { u in
                LibraryTrack(path: u.path, title: Self.titleFromFile(u), number: Self.numberFromFile(u))
            }
            albums.append(LibraryAlbum(title: t ?? URL(fileURLWithPath: folder).lastPathComponent,
                                       artist: a ?? "", albumID: nil, folder: folder,
                                       bitDepth: q.depth, rate: q.rate, format: q.format, added: Date(),
                                       tracks: tracks.sorted { $0.number < $1.number }))
            added += 1
        }
        prune()
        save()
        scanning = false
        status = added == 0 ? "Library is up to date." : "Added \(added) album\(added == 1 ? "" : "s")."
    }

    func remove(_ album: LibraryAlbum) {
        albums.removeAll { $0.folder == album.folder }
        save()
    }

    // MARK: File details

    struct Quality { let depth: Int; let rate: Double; let format: String }

    func probe(_ url: URL) async -> Quality {
        let ext = url.pathExtension.uppercased()
        let format = ext == "M4A" ? "ALAC/AAC" : ext
        guard let ffprobe = Shell.which("ffprobe") else { return Quality(depth: 0, rate: 0, format: format) }
        let r = await runner.capture(ffprobe, ["-v", "error", "-select_streams", "a:0",
                                               "-show_entries", "stream=bits_per_raw_sample,sample_rate,codec_name",
                                               "-of", "default=nw=1", url.path])
        var depth = 0, rate = 0.0, codec = ""
        for line in r.lines {
            let parts = line.split(separator: "=", maxSplits: 1).map(String.init)
            guard parts.count == 2 else { continue }
            switch parts[0] {
            case "bits_per_raw_sample": depth = Int(parts[1]) ?? 0
            case "sample_rate": rate = (Double(parts[1]) ?? 0) / 1000
            case "codec_name": codec = parts[1]
            default: break
            }
        }
        if ext == "M4A" { return Quality(depth: depth, rate: rate, format: codec == "alac" ? "ALAC" : "AAC") }
        if ext == "WAV", depth == 0 { depth = 24 }
        return Quality(depth: depth, rate: rate, format: format)
    }

    static func numberFromFile(_ u: URL) -> Int {
        let name = u.deletingPathExtension().lastPathComponent
        let digits = name.prefix { $0.isNumber }
        return Int(digits) ?? 0
    }

    static func titleFromFile(_ u: URL) -> String {
        var name = u.deletingPathExtension().lastPathComponent
        if let r = name.range(of: #"^\d+[\.\s_-]+"#, options: .regularExpression) { name.removeSubrange(r) }
        if let r = name.range(of: " - ") { name = String(name[r.upperBound...]) }
        return name.trimmed
    }

    /// "Artist - Album (Year) [FLAC] [24B-96kHz]" → ("Album", "Artist")
    static func guess(folder: String) -> (String?, String?) {
        var s = folder.replacingOccurrences(of: #"\s*\[[^\]]*\]"#, with: "", options: .regularExpression)
        s = s.replacingOccurrences(of: #"\s*\(\d{4}\)"#, with: "", options: .regularExpression).trimmed
        if let r = s.range(of: " - ") {
            return (String(s[r.upperBound...]).trimmed, String(s[..<r.lowerBound]).trimmed)
        }
        return (s.isEmpty ? nil : s, nil)
    }

    // MARK: BPM and key

    func analyze(_ album: LibraryAlbum) async {
        guard let ffmpeg = Shell.which("ffmpeg") else {
            status = "ffmpeg isn't installed — use QDL → Update Download Engine."
            return
        }
        analyzing.insert(album.folder)
        defer { analyzing.remove(album.folder) }
        for track in album.tracks where !track.analyzed {
            let raw = FileManager.default.temporaryDirectory.appendingPathComponent("qdl-\(UUID().uuidString).raw")
            let code = await runner.run(ffmpeg, ["-v", "error", "-y", "-ss", "15", "-t", "75", "-i", track.path,
                                                 "-ac", "1", "-ar", "22050", "-f", "f32le", raw.path]) { _ in }
            guard code == 0 else { continue }
            let samples = Analyzer.loadRaw(raw)
            try? FileManager.default.removeItem(at: raw)
            let result = await Task.detached(priority: .utility) {
                Analyzer.analyze(samples: samples, rate: 22050)
            }.value
            guard let ai = albums.firstIndex(where: { $0.folder == album.folder }),
                  let ti = albums[ai].tracks.firstIndex(where: { $0.path == track.path }) else { continue }
            albums[ai].tracks[ti].bpm = result.bpm
            albums[ai].tracks[ti].key = result.key
            albums[ai].tracks[ti].camelot = result.camelot
            albums[ai].tracks[ti].analyzed = true
            save()
        }
    }

    // MARK: Apple Music

    func addToMusic(_ album: LibraryAlbum, mode: AppleMusicMode) async {
        status = "Adding \(album.title) to Apple Music…"
        var files: [URL] = []
        let ffmpeg = Shell.which("ffmpeg")
        let staging = app.folder.appendingPathComponent("Apple Music", isDirectory: true)
            .appendingPathComponent(album.folderURL.lastPathComponent, isDirectory: true)
        for t in album.tracks {
            let ext = t.url.pathExtension.lowercased()
            let musicReads = ["m4a", "mp3", "wav", "aif", "aiff"].contains(ext)
            if musicReads && (mode == .original || ext == "m4a" || ext == "mp3") {
                files.append(t.url)
                continue
            }
            guard let ffmpeg else { continue }
            try? FileManager.default.createDirectory(at: staging, withIntermediateDirectories: true)
            let out = staging.appendingPathComponent(t.url.deletingPathExtension().lastPathComponent + ".m4a")
            if !FileManager.default.fileExists(atPath: out.path) {
                let code = await runner.run(ffmpeg, ["-v", "error", "-y", "-i", t.path, "-map", "0:a:0",
                                                     "-map", "0:v?", "-c:v", "copy", "-disposition:v", "attached_pic",
                                                     "-c:a", "alac", "-map_metadata", "0", out.path]) { _ in }
                if code != 0 {
                    // Retry without artwork, which some files can't carry over.
                    _ = await runner.run(ffmpeg, ["-v", "error", "-y", "-i", t.path, "-map", "0:a:0",
                                                  "-c:a", "alac", "-map_metadata", "0", out.path]) { _ in }
                }
            }
            if FileManager.default.fileExists(atPath: out.path) { files.append(out) }
        }
        guard !files.isEmpty else {
            status = "Nothing to add — ffmpeg is needed to convert these files."
            return
        }
        let list = files.map { "POSIX file \"" + $0.path.replacingOccurrences(of: "\"", with: "\\\"") + "\"" }
            .joined(separator: ", ")
        let script = "tell application \"Music\" to add {\(list)}"
        let code = await runner.run("/usr/bin/osascript", ["-e", script]) { [weak self] line in
            Task { @MainActor in self?.app.appendLog("Apple Music: " + line, isError: true) }
        }
        status = code == 0 ? "Added \(album.title) to Apple Music." : "Apple Music didn't accept the files — allow QDL under System Settings → Privacy & Security → Automation."
    }
}

Sources/QDL/LibraryViews.swift:
import SwiftUI
import AppKit

struct LibraryView: View {
    @EnvironmentObject var model: AppModel
    @EnvironmentObject var library: LibraryStore
    @Environment(\.qdl) private var t
    @State private var search = ""
    @State private var expanded: Set<String> = []
    @State private var onlyUpgrades = false

    private var shown: [LibraryAlbum] {
        let q = search.trimmed.lowercased()
        return library.albums.filter { a in
            (!onlyUpgrades || a.canUpgrade) &&
            (q.isEmpty || a.title.lowercased().contains(q) || a.artist.lowercased().contains(q) ||
             a.tracks.contains { $0.title.lowercased().contains(q) })
        }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            HStack(alignment: .bottom) {
                VStack(alignment: .leading, spacing: 4) {
                    Text("\(library.albums.count) ALBUM\(library.albums.count == 1 ? "" : "S") · \(model.folderDisplay)")
                        .font(.system(size: 12, weight: .semibold))
                        .foregroundStyle(t.sub)
                    Text("Library").font(.system(size: 36, weight: .bold))
                }
                Spacer()
                if library.scanning { ProgressView().controlSize(.small) }
                Button("Scan Folder") { Task { await library.scan() } }
                    .disabled(library.scanning)
                Button("Show in Finder") { model.revealFolder() }
            }

            HStack(spacing: 10) {
                HStack(spacing: 6) {
                    Image(systemName: "magnifyingglass").foregroundStyle(t.sub)
                    TextField("Search your library", text: $search).textFieldStyle(.plain)
                }
                .padding(.horizontal, 12)
                .frame(height: 32)
                .glass(16)
                .frame(maxWidth: 360)
                Toggle("Only albums with a better version on Qobuz", isOn: $onlyUpgrades)
                    .toggleStyle(.checkbox)
                    .font(.system(size: 12.5))
                Spacer()
                if let s = library.status {
                    Text(s).font(.system(size: 12)).foregroundStyle(t.sub).lineLimit(1)
                }
            }

            if library.albums.isEmpty {
                VStack(spacing: 10) {
                    Image(systemName: "music.note.house").font(.system(size: 44, weight: .light)).foregroundStyle(t.faint)
                    Text("Nothing in your library yet").font(.system(size: 17, weight: .semibold))
                    Text("Albums you download appear here. Already have music in your download folder? Use Scan Folder.")
                        .foregroundStyle(t.sub)
                        .multilineTextAlignment(.center)
                        .frame(maxWidth: 420)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else {
                ScrollView {
                    LazyVStack(spacing: 10) {
                        ForEach(shown) { album in
                            LibraryAlbumRow(album: album, expanded: expanded.contains(album.id)) {
                                if expanded.contains(album.id) { expanded.remove(album.id) } else { expanded.insert(album.id) }
                            }
                        }
                    }
                    .padding(.vertical, 4)
                }
            }
        }
        .padding(.horizontal, 24)
        .padding(.top, 18)
        .padding(.bottom, 8)
        .task { library.prune() }
    }
}

struct LibraryAlbumRow: View {
    @EnvironmentObject var model: AppModel
    @EnvironmentObject var library: LibraryStore
    @Environment(\.qdl) private var t
    let album: LibraryAlbum
    let expanded: Bool
    let toggle: () -> Void

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            HStack(spacing: 14) {
                LocalCover(url: album.coverURL, size: 56)
                    .onDrag { NSItemProvider(object: album.folderURL as NSURL) }
                VStack(alignment: .leading, spacing: 3) {
                    HStack(spacing: 8) {
                        Text(album.title).font(.system(size: 15, weight: .semibold)).lineLimit(1)
                        Badge(text: album.qualityText, gold: album.bitDepth >= 24)
                        if album.canUpgrade {
                            Badge(text: "Better on Qobuz: \(Preview.qualityText(bitDepth: album.bestBitDepth, rate: album.bestRate))")
                        }
                    }
                    Text("\(album.artist.isEmpty ? "Unknown artist" : album.artist) · \(album.tracks.count) track\(album.tracks.count == 1 ? "" : "s")")
                        .font(.system(size: 12.5))
                        .foregroundStyle(t.sub)
                        .lineLimit(1)
                }
                Spacer(minLength: 8)
                if library.analyzing.contains(album.folder) {
                    HStack(spacing: 6) {
                        ProgressView().controlSize(.small)
                        Text("Detecting BPM & key").font(.system(size: 11.5)).foregroundStyle(t.sub)
                    }
                }
                Menu {
                    if album.canUpgrade, let id = album.albumID {
                        Button("Open on Qobuz to Upgrade") { model.openLink("https://open.qobuz.com/album/\(id)") }
                    } else if let id = album.albumID {
                        Button("Open on Qobuz") { model.openLink("https://open.qobuz.com/album/\(id)") }
                    }
                    Button("Show in Finder") { NSWorkspace.shared.activateFileViewerSelecting([album.folderURL]) }
                    Button("Add to Apple Music") { Task { await library.addToMusic(album, mode: model.musicMode) } }
                    Button("Detect BPM & Key") { Task { await library.analyze(album) } }
                        .disabled(library.analyzing.contains(album.folder))
                    Divider()
                    Button("Remove from Library (keeps files)") { library.remove(album) }
                } label: {
                    Image(systemName: "ellipsis.circle").font(.system(size: 17))
                }
                .menuStyle(.borderlessButton)
                .menuIndicator(.hidden)
                .fixedSize()
                .help("More")
                Button(action: toggle) {
                    Image(systemName: "chevron.down")
                        .rotationEffect(.degrees(expanded ? 180 : 0))
                        .frame(width: 28, height: 28)
                        .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
                .accessibilityLabel(expanded ? "Hide tracks" : "Show tracks")
            }
            .padding(12)
            .contentShape(Rectangle())
            .onTapGesture(count: 2) { toggle() }

            if expanded {
                VStack(spacing: 0) {
                    HStack(spacing: 10) {
                        Text("#").frame(width: 26, alignment: .leading)
                        Text("TITLE")
                        Spacer()
                        Text("BPM").frame(width: 56, alignment: .trailing)
                        Text("KEY").frame(width: 110, alignment: .trailing)
                        Color.clear.frame(width: 22, height: 1)
                    }
                    .font(.system(size: 10.5, weight: .semibold))
                    .foregroundStyle(t.sub)
                    .padding(.horizontal, 16)
                    .padding(.bottom, 4)
                    ForEach(album.tracks) { track in
                        LibraryTrackRow(track: track)
                    }
                    Text("Tip: drag a track — or the album cover — straight into Premiere Pro, Resolve or Finder.")
                        .font(.system(size: 11))
                        .foregroundStyle(t.faint)
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .padding(.horizontal, 16)
                        .padding(.top, 8)
                }
                .padding(.bottom, 12)
            }
        }
        .glass(16)
    }
}

struct LibraryTrackRow: View {
    @Environment(\.qdl) private var t
    let track: LibraryTrack

    var body: some View {
        HStack(spacing: 10) {
            Text(track.number > 0 ? "\(track.number)" : "–")
                .font(.system(size: 12).monospacedDigit())
                .foregroundStyle(t.faint)
                .frame(width: 26, alignment: .leading)
            Text(track.title).font(.system(size: 13)).lineLimit(1)
            Spacer()
            Text(track.bpm.map { $0.rounded() == $0 ? String(Int($0)) : String(format: "%.1f", $0) } ?? (track.analyzed ? "–" : ""))
                .font(.system(size: 12.5).monospacedDigit())
                .foregroundStyle(t.sub)
                .frame(width: 56, alignment: .trailing)
            Text(keyText)
                .font(.system(size: 12.5))
                .foregroundStyle(t.sub)
                .frame(width: 110, alignment: .trailing)
                .lineLimit(1)
            Image(systemName: "line.3.horizontal")
                .font(.system(size: 11))
                .foregroundStyle(t.faint)
                .frame(width: 22)
                .help("Drag into your editor")
        }
        .padding(.horizontal, 16)
        .frame(minHeight: 30)
        .contentShape(Rectangle())
        .onDrag { NSItemProvider(object: track.url as NSURL) }
        .contextMenu {
            Button("Show in Finder") { NSWorkspace.shared.activateFileViewerSelecting([track.url]) }
            Button("Open") { NSWorkspace.shared.open(track.url) }
        }
    }

    private var keyText: String {
        guard let k = track.key else { return track.analyzed ? "–" : "" }
        if let c = track.camelot { return "\(k) · \(c)" }
        return k
    }
}

struct LocalCover: View {
    let url: URL?
    let size: CGFloat

    var body: some View {
        Group {
            if let url, let img = NSImage(contentsOf: url) {
                Image(nsImage: img).resizable().aspectRatio(contentMode: .fill)
            } else {
                CoverView(size: size, radius: 8)
            }
        }
        .frame(width: size, height: size)
        .clipShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
        .accessibilityHidden(true)
    }
}

/// On an album page: "you already have this" and the upgrade offer.
struct InLibraryBanner: View {
    @EnvironmentObject var model: AppModel
    @EnvironmentObject var library: LibraryStore
    @Environment(\.qdl) private var t
    let preview: Preview

    var body: some View {
        if preview.kind == "album", let have = library.match(for: preview) {
            let better = preview.maxBitDepth > have.bitDepth ||
                (preview.maxBitDepth == have.bitDepth && preview.maxSampleRate > have.rate + 0.5)
            HStack(spacing: 12) {
                Image(systemName: "checkmark.circle.fill").foregroundStyle(t.ok)
                VStack(alignment: .leading, spacing: 2) {
                    Text("Already in your library · \(have.qualityText)").font(.system(size: 13, weight: .semibold))
                    Text(better ? "Qobuz has it in \(preview.bestText) — better than your copy."
                                : "Your copy is already the best quality Qobuz offers.")
                        .font(.system(size: 12))
                        .foregroundStyle(t.sub)
                }
                Spacer()
                Button("Show in Finder") { NSWorkspace.shared.activateFileViewerSelecting([have.folderURL]) }
                if better {
                    AccentButton(title: "Upgrade to \(preview.bestText)", icon: "arrow.up.circle.fill") {
                        model.upgrade(preview)
                    }
                }
            }
            .padding(12)
            .glass(14)
        }
    }
}
